// ---- Config ----
#[derive(Debug, Deserialize, Default)]
struct Config {
    finish_hook: Option<String>,
    paranoid_history_mode_default: Option<bool>,
    autoeval_mode_default: Option<bool>,
    history_size: Option<usize>,
    cmdlist_always_show_preview: Option<bool>,
    cmd_timeout_millis: Option<u64>,
    highlighting_enabled: Option<bool>,
    eval_environment: Option<Vec<String>>,
    snippets: Option<HashMap<String, String>>,
    help_viewers: Option<HashMap<String, String>>,
    output_viewers: Option<HashMap<String, String>>,
}

impl Config {
    fn load() -> Self {
        let config_path = config_file_path();
        if let Some(path) = config_path {
            if path.exists() {
                if let Ok(contents) = fs::read_to_string(&path) {
                    if let Ok(config) = toml::from_str(&contents) {
                        return config;
                    }
                }
            }
        }
        Config::default()
    }

    fn paranoid_history_mode_default(&self) -> bool {
        self.paranoid_history_mode_default.unwrap_or(false)
    }

    fn autoeval_mode_default(&self) -> bool {
        self.autoeval_mode_default.unwrap_or(true)
    }

    fn history_size(&self) -> usize {
        self.history_size.unwrap_or(500)
    }

    fn cmd_timeout_millis(&self) -> u64 {
        self.cmd_timeout_millis.unwrap_or(2000)
    }

    fn eval_environment(&self) -> Vec<String> {
        self.eval_environment
            .clone()
            .unwrap_or_else(|| vec!["bash".to_string(), "-c".to_string()])
    }
}

fn config_file_path() -> Option<PathBuf> {
    dirs::home_dir().map(|h| h.join(".config").join("pipr").join("pipr.toml"))
}

// ---- History ----
struct History {
    entries: Vec<String>,
    max_size: usize,
    /// Index into history for navigation (None = current/new)
    nav_index: Option<usize>,
}

impl History {
    fn new(max_size: usize) -> Self {
        // Load from file
        let entries = load_history();
        History { entries, max_size, nav_index: None }
    }

    fn push(&mut self, cmd: &str) {
        if cmd.trim().is_empty() {
            return;
        }
        // Remove duplicate if exists at end
        if self.entries.last().map(|e| e == cmd).unwrap_or(false) {
            return;
        }
        self.entries.push(cmd.to_string());
        if self.entries.len() > self.max_size {
            self.entries.remove(0);
        }
        self.nav_index = None;
        save_history(&self.entries);
    }

    fn prev(&mut self, current: &str) -> Option<String> {
        if self.entries.is_empty() {
            return None;
        }
        match self.nav_index {
            None => {
                // Start from the end
                let idx = self.entries.len() - 1;
                self.nav_index = Some(idx);
                Some(self.entries[idx].clone())
            }
            Some(0) => {
                // Already at beginning
                Some(self.entries[0].clone())
            }
            Some(i) => {
                let new_idx = i - 1;
                self.nav_index = Some(new_idx);
                Some(self.entries[new_idx].clone())
            }
        }
    }

    fn next(&mut self) -> Option<String> {
        match self.nav_index {
            None => None,
            Some(i) if i + 1 >= self.entries.len() => {
                self.nav_index = None;
                Some(String::new())
            }
            Some(i) => {
                let new_idx = i + 1;
                self.nav_index = Some(new_idx);
                Some(self.entries[new_idx].clone())
            }
        }
    }

    fn reset_nav(&mut self) {
        self.nav_index = None;
    }
}

fn history_file_path() -> Option<PathBuf> {
    dirs::home_dir().map(|h| h.join(".config").join("pipr").join("history"))
}

fn load_history() -> Vec<String> {
    if let Some(path) = history_file_path() {
        if path.exists() {
            if let Ok(contents) = fs::read_to_string(&path) {
                return contents.lines().filter(|l| !l.is_empty()).map(|l| l.to_string()).collect();
            }
        }
    }
    Vec::new()
}

fn save_history(entries: &[String]) {
    if let Some(path) = history_file_path() {
        if let Some(parent) = path.parent() {
            let _ = fs::create_dir_all(parent);
        }
        let content = entries.join("\n");
        let _ = fs::write(&path, content);
    }
}

// ---- Bookmarks ----
fn bookmarks_file_path() -> Option<PathBuf> {
    dirs::home_dir().map(|h| h.join(".config").join("pipr").join("bookmarks"))
}

fn load_bookmarks() -> Vec<String> {
    if let Some(path) = bookmarks_file_path() {
        if path.exists() {
            if let Ok(contents) = fs::read_to_string(&path) {
                return contents.lines().filter(|l| !l.is_empty()).map(|l| l.to_string()).collect();
            }
        }
    }
    Vec::new()
}

fn save_bookmarks(bookmarks: &[String]) {
    if let Some(path) = bookmarks_file_path() {
        if let Some(parent) = path.parent() {
            let _ = fs::create_dir_all(parent);
        }
        let content = bookmarks.join("\n");
        let _ = fs::write(&path, content);
    }
}

// ---- Text buffer (multi-line) ----
#[derive(Clone, Debug)]
struct TextBuffer {
    lines: Vec<String>,
    /// cursor position: (line_idx, col_idx)
    cursor: (usize, usize),
}

impl TextBuffer {
    fn new() -> Self {
        TextBuffer {
            lines: vec![String::new()],
            cursor: (0, 0),
        }
    }

    fn from_str(s: &str) -> Self {
        let lines: Vec<String> = s.split('\n').map(|l| l.to_string()).collect();
        let last = lines.len() - 1;
        let col = lines[last].len();
        TextBuffer {
            lines,
            cursor: (last, col),
        }
    }

    fn to_string_raw(&self) -> String {
        self.lines.join("\n")
    }

    /// Join lines with spaces (non-raw mode)
    fn to_command(&self, raw: bool) -> String {
        if raw {
            self.lines.join("\n")
        } else {
            self.lines.join(" ")
        }
    }

    fn insert_char(&mut self, c: char) {
        let (row, col) = self.cursor;
        self.lines[row].insert(col, c);
        self.cursor = (row, col + 1);
    }

    fn insert_newline(&mut self) {
        let (row, col) = self.cursor;
        let rest = self.lines[row].split_off(col);
        self.lines.insert(row + 1, rest);
        self.cursor = (row + 1, 0);
    }

    fn delete_char_back(&mut self) {
        let (row, col) = self.cursor;
        if col > 0 {
            self.lines[row].remove(col - 1);
            self.cursor = (row, col - 1);
        } else if row > 0 {
            // Merge with previous line
            let current = self.lines.remove(row);
            let prev_len = self.lines[row - 1].len();
            self.lines[row - 1].push_str(&current);
            self.cursor = (row - 1, prev_len);
        }
    }

    fn delete_char_forward(&mut self) {
        let (row, col) = self.cursor;
        if col < self.lines[row].len() {
            self.lines[row].remove(col);
        } else if row + 1 < self.lines.len() {
            let next = self.lines.remove(row + 1);
            self.lines[row].push_str(&next);
        }
    }

    fn move_left(&mut self) {
        let (row, col) = self.cursor;
        if col > 0 {
            self.cursor = (row, col - 1);
        } else if row > 0 {
            let prev_len = self.lines[row - 1].len();
            self.cursor = (row - 1, prev_len);
        }
    }

    fn move_right(&mut self) {
        let (row, col) = self.cursor;
        if col < self.lines[row].len() {
            self.cursor = (row, col + 1);
        } else if row + 1 < self.lines.len() {
            self.cursor = (row + 1, 0);
        }
    }

    fn move_home(&mut self) {
        self.cursor.1 = 0;
    }

    fn move_end(&mut self) {
        let row = self.cursor.0;
        self.cursor.1 = self.lines[row].len();
    }

    fn move_up(&mut self) {
        let (row, col) = self.cursor;
        if row > 0 {
            let new_col = col.min(self.lines[row - 1].len());
            self.cursor = (row - 1, new_col);
        }
    }

    fn move_down(&mut self) {
        let (row, col) = self.cursor;
        if row + 1 < self.lines.len() {
            let new_col = col.min(self.lines[row + 1].len());
            self.cursor = (row + 1, new_col);
        }
    }

    fn delete_word_back(&mut self) {
        let (row, col) = self.cursor;
        if col == 0 {
            if row > 0 {
                self.delete_char_back();
            }
            return;
        }
        let line = &self.lines[row];
        // Skip trailing spaces
        let mut pos = col;
        while pos > 0 && line.chars().nth(pos - 1).map(|c| c == ' ').unwrap_or(false) {
            pos -= 1;
        }
        // Delete word chars
        while pos > 0 && line.chars().nth(pos - 1).map(|c| c != ' ').unwrap_or(false) {
            pos -= 1;
        }
        self.lines[row].drain(pos..col);
        self.cursor = (row, pos);
    }

    fn clear(&mut self) {
        self.lines = vec![String::new()];
        self.cursor = (0, 0);
    }

    /// Returns the absolute cursor position (character index from start of all text)
    fn abs_cursor_pos(&self) -> usize {
        let mut pos = 0;
        for (i, line) in self.lines.iter().enumerate() {
            if i == self.cursor.0 {
                pos += self.cursor.1;
                break;
            }
            pos += line.len() + 1; // +1 for newline
        }
        pos
    }

    /// Get the character at the cursor position
    fn char_at_cursor(&self) -> Option<char> {
        let (row, col) = self.cursor;
        self.lines[row].chars().nth(col)
    }

    /// Find the word at cursor position (for F5)
    fn word_at_cursor(&self) -> String {
        let (row, col) = self.cursor;
        let line = &self.lines[row];
        let chars: Vec<char> = line.chars().collect();
        if chars.is_empty() {
            return String::new();
        }
        let col = col.min(chars.len().saturating_sub(1));
        // Find word boundaries
        let mut start = col;
        let mut end = col;
        while start > 0 && chars[start - 1] != ' ' {
            start -= 1;
        }
        while end < chars.len() && chars[end] != ' ' {
            end += 1;
        }
        chars[start..end].iter().collect()
    }

    /// Returns (prefix_up_to_pipe, suffix_after_pipe) when cursor is on a | character
    fn pipe_split_at_cursor(&self) -> Option<(String, String)> {
        let ch = self.char_at_cursor()?;
        if ch != '|' {
            return None;
        }
        let full = self.to_string_raw();
        let pos = self.abs_cursor_pos();
        let prefix = full[..pos].to_string();
        let suffix = full[pos..].to_string();
        Some((prefix, suffix))
    }

    fn insert_str(&mut self, s: &str) {
        for ch in s.chars() {
            if ch == '\n' {
                self.insert_newline();
            } else {
                self.insert_char(ch);
            }
        }
    }
}

// ---- App State ----
#[derive(Debug, Clone, PartialEq)]
enum AppMode {
    Normal,
    History,
    Bookmarks,
    SnippetMenu,
    HelpViewerMenu,
    OutputViewerMenu,
    Help,
}

struct EvalOutput {
    stdout: String,
    stderr: String,
    is_stale: bool,
}

struct CacheState {
    /// The command prefix up to the pipe
    prefix: String,
    /// Cached stdout output of prefix
    cached_output: String,
}

struct App {
    config: Config,
    buffer: TextBuffer,
    eval_output: EvalOutput,
    autoeval: bool,
    paranoid: bool,
    is_bookmarked: bool,
    history: History,
    bookmarks: Vec<String>,
    mode: AppMode,
    // For list panels
    list_state: ListState,
    // Cache state
    cache: Option<CacheState>,
    caching_active: bool,
    // Options
    raw_mode: bool,
    out_file: Option<PathBuf>,
    no_isolation: bool,
}

impl App {
    fn new(config: Config, default_text: Option<String>, raw_mode: bool, out_file: Option<PathBuf>, no_isolation: bool) -> Self {
        let autoeval = config.autoeval_mode_default();
        let paranoid = config.paranoid_history_mode_default();
        let history_size = config.history_size();
        let history = History::new(history_size);
        let bookmarks = load_bookmarks();

        let mut buf = TextBuffer::new();
        if let Some(text) = default_text {
            buf = TextBuffer::from_str(&text);
        }

        let mut app = App {
            config,
            buffer: buf,
            eval_output: EvalOutput {
                stdout: String::new(),
                stderr: String::new(),
                is_stale: true,
            },
            autoeval,
            paranoid,
            is_bookmarked: false,
            history,
            bookmarks,
            mode: AppMode::Normal,
            list_state: ListState::default(),
            cache: None,
            caching_active: false,
            raw_mode,
            out_file,
            no_isolation,
        };
        app.check_bookmarked();
        if autoeval && !app.buffer.to_command(false).trim().is_empty() {
            app.evaluate();
        }
        app
    }

    fn check_bookmarked(&mut self) {
        let cmd = self.buffer.to_command(false);
        self.is_bookmarked = self.bookmarks.contains(&cmd);
    }

    fn evaluate(&mut self) {
        let cmd = self.build_command_for_eval();
        if cmd.trim().is_empty() {
            self.eval_output = EvalOutput {
                stdout: String::new(),
                stderr: String::new(),
                is_stale: false,
            };
            return;
        }

        let timeout_ms = self.config.cmd_timeout_millis();
        let env = self.config.eval_environment();

        let (stdout, stderr) = run_command_with_timeout(&env, &cmd, timeout_ms);
        self.eval_output = EvalOutput {
            stdout,
            stderr,
            is_stale: false,
        };

        // Add to history if paranoid mode
        if self.paranoid && stderr.is_empty() {
            // Actually evaluate and check success - but we don't have exit code easily
            // paranoid: save every successfully running command
        }
    }

    fn build_command_for_eval(&self) -> String {
        // Build the command, filtering out lines starting with #
        let raw = self.buffer.to_string_raw();
        let filtered: Vec<&str> = raw.lines()
            .filter(|l| !l.trim_start().starts_with('#'))
            .collect();
        let joined = filtered.join(" ");

        // If caching is active, we use cached output as stdin for the suffix
        if self.caching_active {
            if let Some(ref cache) = self.cache {
                // The suffix part after the pipe
                let full = self.buffer.to_string_raw();
                // Find the cached prefix in full command
                // The cached prefix is stored; use it to find the split
                // Build: echo cached_output | <suffix>
                // Actually: cat <(echo cached_output) | <rest of command after pipe>
                // We need to find where the pipe split was
                let full_filtered: Vec<&str> = full.lines()
                    .filter(|l| !l.trim_start().starts_with('#'))
                    .collect();
                let full_joined = full_filtered.join(" ");

                // Find the first occurrence of the split
                if let Some(pipe_pos) = find_first_pipe_pos(&cache.prefix) {
                    // suffix is everything after the pipe in the current command
                    let suffix = &full_joined[full_joined.find('|').unwrap_or(0)..];
                    let cached = &cache.cached_output;
                    // Use printf to pass cached data
                    return format!("printf '%s' {} {}", shell_escape(cached), suffix);
                }
            }
        }

        joined
    }

    fn evaluate_and_maybe_save_history(&mut self) {
        self.evaluate();
        // Save to history on Enter press (always save on Enter)
        let cmd = self.buffer.to_command(self.raw_mode);
        if !cmd.trim().is_empty() {
            self.history.push(&cmd);
        }
    }

    fn on_text_change(&mut self) {
        self.check_bookmarked();
        self.eval_output.is_stale = true;
        // Invalidate cache if the prefix part changed
        if self.caching_active {
            if let Some(ref cache) = self.cache {
                // Check if prefix part is still the same
                let full = self.buffer.to_string_raw();
                let filtered: Vec<&str> = full.lines()
                    .filter(|l| !l.trim_start().starts_with('#'))
                    .collect();
                let joined = filtered.join(" ");
                if !joined.starts_with(&cache.prefix) {
                    // Prefix changed, invalidate cache
                    self.caching_active = false;
                    self.cache = None;
                }
            }
        }
        if self.autoeval {
            self.evaluate();
            if self.paranoid && self.eval_output.stderr.is_empty() && !self.eval_output.stdout.is_empty() {
                let cmd = self.buffer.to_command(self.raw_mode);
                if !cmd.trim().is_empty() {
                    self.history.push(&cmd);
                }
            }
        }
    }

    fn toggle_cache(&mut self) {
        // Toggle caching at the current pipe position
        if self.caching_active {
            // Toggle off
            self.caching_active = false;
            self.cache = None;
            return;
        }

        // Check if cursor is on a |
        let ch = self.buffer.char_at_cursor();
        if ch == Some('|') {
            // Get prefix part
            let full = self.buffer.to_string_raw();
            let pos = self.buffer.abs_cursor_pos();
            let prefix_raw = &full[..pos];
            // Filter # lines from prefix
            let filtered_prefix: Vec<&str> = prefix_raw.lines()
                .filter(|l| !l.trim_start().starts_with('#'))
                .collect();
            let prefix = filtered_prefix.join(" ");

            // Execute prefix to get cached output
            let timeout_ms = self.config.cmd_timeout_millis();
            let env = self.config.eval_environment();
            let (stdout, _stderr) = run_command_with_timeout(&env, &prefix, timeout_ms);

            self.cache = Some(CacheState {
                prefix: prefix.clone(),
                cached_output: stdout,
            });
            self.caching_active = true;
        }
    }

    fn toggle_bookmark(&mut self) {
        let cmd = self.buffer.to_command(false);
        if cmd.trim().is_empty() {
            return;
        }
        if self.is_bookmarked {
            self.bookmarks.retain(|b| b != &cmd);
            self.is_bookmarked = false;
        } else {
            self.bookmarks.push(cmd);
            self.is_bookmarked = true;
        }
        save_bookmarks(&self.bookmarks);
    }

    fn current_command_word_for_help(&self) -> String {
        // Get the first word of the line the cursor is on, or the word at cursor
        let word = self.buffer.word_at_cursor();
        if word.is_empty() {
            // Get the first word of the current line
            let (row, _) = self.buffer.cursor;
            let line = &self.buffer.lines[row];
            line.split_whitespace().next().unwrap_or("").to_string()
        } else {
            word
        }
    }

    fn select_from_list(&mut self) -> Option<String> {
        let idx = self.list_state.selected()?;
        match self.mode {
            AppMode::History => {
                if idx < self.history.entries.len() {
                    let entry = self.history.entries[self.history.entries.len() - 1 - idx].clone();
                    // history is displayed newest-last, so idx 0 = newest
                    // Actually: history panel shows entries where last is >> selected
                    // Let's recalculate: shown with >> at bottom = current
                    Some(entry)
                } else {
                    None
                }
            }
            AppMode::Bookmarks => {
                if idx < self.bookmarks.len() {
                    Some(self.bookmarks[idx].clone())
                } else {
                    None
                }
            }
            _ => None,
        }
    }
}

fn find_first_pipe_pos(s: &str) -> Option<usize> {
    s.find('|')
}

fn shell_escape(s: &str) -> String {
    format!("'{}'", s.replace('\'', "'\\''"))
}

fn run_command_with_timeout(env: &[String], cmd: &str, timeout_ms: u64) -> (String, String) {
    if cmd.trim().is_empty() {
        return (String::new(), String::new());
    }

    if env.is_empty() {
        return (String::new(), "No eval environment configured".to_string());
    }

    let shell = &env[0];
    let args = &env[1..];

    let child = Command::new(shell)
        .args(args)
        .arg(cmd)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn();

    match child {
        Err(e) => (String::new(), format!("Failed to spawn: {}", e)),
        Ok(mut child) => {
            let start = Instant::now();
            let timeout = Duration::from_millis(timeout_ms);

            loop {
                match child.try_wait() {
                    Ok(Some(_status)) => {
                        let output = child.wait_with_output().unwrap_or_default();
                        let stdout = String::from_utf8_lossy(&output.stdout).to_string();
                        let stderr = String::from_utf8_lossy(&output.stderr).to_string();
                        return (stdout, stderr);
                    }
                    Ok(None) => {
                        if start.elapsed() >= timeout {
                            let _ = child.kill();
                            let _ = child.wait();
                            return (String::new(), "Command timed out".to_string());
                        }
                        std::thread::sleep(Duration::from_millis(50));
                    }
                    Err(_) => {
                        return (String::new(), "Wait error".to_string());
                    }
                }
            }
        }
    }
}

