fn ui(f: &mut Frame, app: &App) {
    let size = f.size();

    match app.mode {
        AppMode::Help => {
            let help_text = vec![
                Line::from("F1         Show/hide help"),
                Line::from("F2         Toggle autoeval"),
                Line::from("F3         Toggle Paranoid history (fills up history in autoeval)"),
                Line::from("F4         Show/hide history"),
                Line::from("Ctrl+B     Show/hide bookmarks"),
                Line::from("F5         Open helpviewer"),
                Line::from("F6         Open outputviewer"),
                Line::from("F7         When the cursor is on a `|` symbol, cache the output of everythin"),
                Line::from("Ctrl+S     Save bookmark"),
                Line::from("Alt+Return Newline"),
                Line::from("Ctrl+U     Clear Command"),
                Line::from("Ctrl+P     Previous in history"),
                Line::from("Ctrl+N     Next in history"),
                Line::from("Ctrl+V     Insert snippet (press corresponding key to choose)"),
                Line::from(""),
                Line::from("disable a line by starting it with a #"),
                Line::from("this will simply exclude the line from the executed command."),
                Line::from(""),
                Line::from("Config file is in"),
                Line::from("~/.config/pipr/pipr.toml"),
            ];

            let block = Block::default()
                .borders(Borders::ALL)
                .title(" Help ");

            let paragraph = Paragraph::new(help_text)
                .block(block);

            let help_area = Rect {
                x: size.x + 1,
                y: size.y,
                width: size.width.saturating_sub(2),
                height: size.height.saturating_sub(1),
            };

            f.render_widget(paragraph, help_area);
            render_bottom_bar(f, size);
        }
        AppMode::History => {
            render_list_panel(f, app, "History", size);
            render_bottom_bar(f, size);
        }
        AppMode::Bookmarks => {
            render_list_panel(f, app, "Bookmarks", size);
            render_bottom_bar(f, size);
        }
        AppMode::SnippetMenu | AppMode::HelpViewerMenu | AppMode::OutputViewerMenu => {
            // Render main view behind popup
            let chunks = Layout::default()
                .direction(Direction::Vertical)
                .constraints([Constraint::Length(3), Constraint::Min(0)])
                .split(Rect {
                    x: size.x,
                    y: size.y,
                    width: size.width,
                    height: size.height.saturating_sub(0),
                });

            // Split into popup and main
            let popup_width = 30u16;
            let main_area = Rect {
                x: size.x + popup_width,
                y: size.y,
                width: size.width.saturating_sub(popup_width),
                height: size.height,
            };
            let popup_area = Rect {
                x: size.x,
                y: size.y,
                width: popup_width,
                height: size.height.saturating_sub(1),
            };

            render_main_view(f, app, main_area);
            render_menu_popup(f, app, popup_area);
            render_bottom_bar(f, size);
        }
        AppMode::Normal => {
            let main_area = Rect {
                x: size.x,
                y: size.y,
                width: size.width,
                height: size.height.saturating_sub(0),
            };
            render_main_view(f, app, main_area);
        }
    }
}

fn render_bottom_bar(f: &mut Frame, size: Rect) {
    // Help: F1 at bottom right
    let help_text = "Help: F1";
    let bar = Paragraph::new(help_text)
        .style(Style::default());
    let bar_area = Rect {
        x: size.x,
        y: size.y + size.height - 1,
        width: size.width,
        height: 1,
    };
    // right align
    let text_width = help_text.len() as u16;
    let text_area = Rect {
        x: size.x + size.width.saturating_sub(text_width + 1),
        y: bar_area.y,
        width: text_width + 1,
        height: 1,
    };
    f.render_widget(bar, text_area);
}

fn render_list_panel(f: &mut Frame, app: &App, title: &str, size: Rect) {
    let panel_height = 10u16;
    let panel_area = Rect {
        x: size.x + 1,
        y: size.y,
        width: size.width.saturating_sub(2),
        height: panel_height,
    };

    let (items, current_idx) = match app.mode {
        AppMode::History => {
            let entries = &app.history.entries;
            let n = entries.len();
            let selected = app.list_state.selected().unwrap_or(n.saturating_sub(1));
            let items: Vec<ListItem> = entries.iter().enumerate().map(|(i, e)| {
                let display = e.replace('\n', " ↵ ");
                let prefix = if i == n.saturating_sub(1).saturating_sub(selected) + n.saturating_sub(1) - (n.saturating_sub(1).saturating_sub(selected)) {
                    ">>"
                } else {
                    "  "
                };
                // Actually simpler: the selected index in list_state maps to position in display
                // We display history with newest at bottom
                // list_state.selected() = index from top of displayed list
                // where top = oldest
                let sel = app.list_state.selected().unwrap_or(n.saturating_sub(1));
                let pfx = if i == sel { ">>" } else { "  " };
                ListItem::new(format!("{}{}", pfx, display))
            }).collect();
            (items, app.list_state.selected().unwrap_or(n.saturating_sub(1)))
        }
        AppMode::Bookmarks => {
            let n = app.bookmarks.len();
            let sel = app.list_state.selected().unwrap_or(0);
            let items: Vec<ListItem> = app.bookmarks.iter().enumerate().map(|(i, b)| {
                let display = b.replace('\n', " ↵ ");
                let pfx = if i == sel { ">>" } else { "  " };
                ListItem::new(format!("{}{}", pfx, display))
            }).collect();
            (items, sel)
        }
        _ => (vec![], 0),
    };

    let block = Block::default()
        .borders(Borders::ALL)
        .title(format!(" {} ", title));

    let list = List::new(items).block(block);
    let mut state = app.list_state.clone();
    f.render_stateful_widget(list, panel_area, &mut state);
}

fn build_command_title(app: &App) -> String {
    let mut parts = vec!["Command".to_string()];
    if app.is_bookmarked { parts.push("Bookmarked".to_string()); }
    if app.autoeval { parts.push("Autoeval".to_string()); }
    if app.caching_active { parts.push("Caching".to_string()); }
    if app.paranoid { parts.push("Paranoid".to_string()); }
    format!(" {} ", parts.join("] ["))
}

fn build_output_title(app: &App) -> String {
    if app.eval_output.is_stale {
        " Output [+] ".to_string()
    } else {
        " Output ".to_string()
    }
}

fn render_main_view(f: &mut Frame, app: &App, area: Rect) {
    let has_stderr = !app.eval_output.stderr.is_empty();

    let constraints = if has_stderr {
        vec![
            Constraint::Length(3),
            Constraint::Ratio(1, 2),
            Constraint::Ratio(1, 2),
        ]
    } else {
        vec![
            Constraint::Length(3),
            Constraint::Min(0),
        ]
    };

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints(constraints)
        .split(area);

    // Command input box
    let cmd_title = build_command_title(app);
    let cmd_block = Block::default()
        .borders(Borders::ALL)
        .title(cmd_title);

    let cmd_text: Vec<Line> = app.buffer.lines.iter().map(|l| Line::from(l.clone())).collect();
    let cmd_para = Paragraph::new(cmd_text)
        .block(cmd_block);

    f.render_widget(cmd_para, chunks[0]);

    // Set cursor position
    let (row, col) = app.buffer.cursor;
    let cursor_x = chunks[0].x + 1 + col as u16;
    let cursor_y = chunks[0].y + 1 + row as u16;
    if cursor_x < chunks[0].x + chunks[0].width - 1
        && cursor_y < chunks[0].y + chunks[0].height - 1 {
        f.set_cursor(cursor_x, cursor_y);
    }

    // Output box
    let out_title = build_output_title(app);
    let out_block = Block::default()
        .borders(Borders::ALL)
        .title(out_title)
        .title_bottom(Line::from("Help: F1").right_aligned());

    let out_text: Vec<Line> = app.eval_output.stdout.lines().map(|l| Line::from(l.to_string())).collect();
    let out_para = Paragraph::new(out_text)
        .block(out_block);
    f.render_widget(out_para, chunks[1]);

    if has_stderr {
        let err_block = Block::default()
            .borders(Borders::ALL)
            .title(" Stderr ")
            .title_bottom(Line::from("Help: F1").right_aligned());
        let err_text: Vec<Line> = app.eval_output.stderr.lines().map(|l| Line::from(l.to_string())).collect();
        let err_para = Paragraph::new(err_text)
            .block(err_block);
        f.render_widget(err_para, chunks[2]);
    }
}

fn render_menu_popup(f: &mut Frame, app: &App, area: Rect) {
    let title = match app.mode {
        AppMode::SnippetMenu => " Open in ",
        AppMode::HelpViewerMenu => " Open in ",
        AppMode::OutputViewerMenu => " Open in ",
        _ => " Menu ",
    };

    let items: Vec<ListItem> = match app.mode {
        AppMode::SnippetMenu => {
            let mut sorted: Vec<(&String, &String)> = app.config.snippets.as_ref()
                .map(|m| m.iter().collect())
                .unwrap_or_default();
            sorted.sort_by_key(|(k, _)| k.clone());
            sorted.iter().map(|(k, v)| {
                let display = v.replace("||", "");
                ListItem::new(format!("{}: {}", k, display))
            }).collect()
        }
        AppMode::HelpViewerMenu => {
            let word = app.current_command_word_for_help();
            let mut sorted: Vec<(&String, &String)> = app.config.help_viewers.as_ref()
                .map(|m| m.iter().collect())
                .unwrap_or_default();
            sorted.sort_by_key(|(k, _)| k.clone());
            sorted.iter().map(|(k, v)| {
                let cmd = v.replace("??", &word);
                ListItem::new(format!("{}: {}", k, cmd))
            }).collect()
        }
        AppMode::OutputViewerMenu => {
            let mut sorted: Vec<(&String, &String)> = app.config.output_viewers.as_ref()
                .map(|m| m.iter().collect())
                .unwrap_or_default();
            sorted.sort_by_key(|(k, _)| k.clone());
            sorted.iter().map(|(k, v)| {
                ListItem::new(format!("{}: {}", k, v))
            }).collect()
        }
        _ => vec![],
    };

    let block = Block::default()
        .borders(Borders::ALL)
        .title(title);
    let list = List::new(items).block(block);
    f.render_widget(list, area);
}

fn run_external_command(cmd_template: &str, replacement: &str, output: &str) {
    // Run the viewer command
    let cmd = cmd_template.replace("??", replacement);

    disable_raw_mode().ok();
    execute!(io::stdout(), LeaveAlternateScreen, DisableMouseCapture).ok();

    // Pipe output to the command or just open it
    let mut child = if output.is_empty() {
        Command::new("sh")
            .arg("-c")
            .arg(&cmd)
            .spawn()
            .ok()
    } else {
        let mut child = Command::new("sh")
            .arg("-c")
            .arg(&cmd)
            .stdin(Stdio::piped())
            .spawn()
            .ok();
        if let Some(ref mut c) = child {
            if let Some(ref mut stdin) = c.stdin {
                let _ = stdin.write_all(output.as_bytes());
            }
        }
        child
    };

    if let Some(ref mut c) = child {
        let _ = c.wait();
    }

    enable_raw_mode().ok();
    execute!(io::stdout(), EnterAlternateScreen, EnableMouseCapture).ok();
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut opts = getopts::Options::new();
    opts.optopt("d", "default", "text inserted into the textfield on startup", "TEXT");
    opts.optopt("o", "out-file", "write final command to file", "FILE");
    opts.optopt("", "in-file", "read initial command from file", "FILE");
    opts.optflag("", "config-reference", "print out the default configuration file");
    opts.optflag("r", "raw-mode", "keep linebreaks in finished command when closing");
    opts.optflag("", "no-isolation", "disable isolation. This will run the commands directly\non your system, without protection. Take care.");
    opts.optflag("h", "help", "print this help menu");

    let matches = match opts.parse(&args[1..]) {
        Ok(m) => m,
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    };

    if matches.opt_present("h") {
        let brief = format!("Usage: {} [options]", args[0]);
        print!("{}", opts.usage(&brief));
        return;
    }

    if matches.opt_present("config-reference") {
        print!("{}", default_config_reference());
        return;
    }

    let no_isolation = matches.opt_present("no-isolation");

    // Check for bwrap if isolation is needed
    if !no_isolation {
        // Check if bwrap is available
        let bwrap_available = Command::new("which")
            .arg("bwrap")
            .output()
            .map(|o| o.status.success())
            .unwrap_or(false);

        if !bwrap_available {
            eprintln!("bubblewrap installation not found. Please make sure you have `bwrap` on your path, or supply --no-isolation to disable safe-mode");
            std::process::exit(1);
        }
    }

    let raw_mode = matches.opt_present("r");
    let out_file = matches.opt_str("o").map(PathBuf::from);

    let default_text = if let Some(in_file) = matches.opt_str("in-file") {
        fs::read_to_string(&in_file).ok()
            .map(|s| s.trim_end_matches('\n').to_string())
    } else {
        matches.opt_str("d")
    };

    let config = Config::load();

    // Setup terminal
    enable_raw_mode().expect("Failed to enable raw mode");
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen, EnableMouseCapture).expect("Failed to enter alternate screen");
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend).expect("Failed to create terminal");

    let mut app = App::new(config, default_text, raw_mode, out_file.clone(), no_isolation);

    // Main loop
    let result = run_app(&mut terminal, &mut app);

    // Cleanup
    disable_raw_mode().ok();
    execute!(
        terminal.backend_mut(),
        LeaveAlternateScreen,
        DisableMouseCapture
    ).ok();
    terminal.show_cursor().ok();

    if let Err(e) = result {
        eprintln!("Error: {}", e);
    }

    // Write output
    let final_cmd = app.buffer.to_command(app.raw_mode);
    if let Some(ref path) = out_file {
        let _ = fs::write(path, &final_cmd);
    }

    // Run finish hook if configured
    if let Some(ref hook) = app.config.finish_hook {
        let mut child = Command::new("sh")
            .arg("-c")
            .arg(hook)
            .stdin(Stdio::piped())
            .spawn()
            .ok();
        if let Some(ref mut c) = child {
            if let Some(ref mut stdin) = c.stdin {
                let _ = stdin.write_all(final_cmd.as_bytes());
            }
            let _ = c.wait();
        }
    }

    // Print final command to stdout
    println!("{}", final_cmd);
}

fn run_app<B: ratatui::backend::Backend>(
    terminal: &mut Terminal<B>,
    app: &mut App,
) -> io::Result<()> {
    loop {
        terminal.draw(|f| ui(f, app))?;

        if !event::poll(Duration::from_millis(100))? {
            continue;
        }

        let ev = event::read()?;

        match ev {
            Event::Key(key) if key.kind == KeyEventKind::Press || key.kind == KeyEventKind::Repeat => {
                match app.mode {
                    AppMode::Normal => {
                        match key.code {
                            KeyCode::Esc => {
                                return Ok(());
                            }
                            KeyCode::F(1) => {
                                app.mode = AppMode::Help;
                            }
                            KeyCode::F(2) => {
                                app.autoeval = !app.autoeval;
                                if app.autoeval {
                                    app.evaluate();
                                }
                            }
                            KeyCode::F(3) => {
                                app.paranoid = !app.paranoid;
                            }
                            KeyCode::F(4) => {
                                app.mode = AppMode::History;
                                let n = app.history.entries.len();
                                if n > 0 {
                                    app.list_state.select(Some(n - 1));
                                } else {
                                    app.list_state.select(None);
                                }
                            }
                            KeyCode::F(5) => {
                                app.mode = AppMode::HelpViewerMenu;
                            }
                            KeyCode::F(6) => {
                                app.mode = AppMode::OutputViewerMenu;
                            }
                            KeyCode::F(7) => {
                                app.toggle_cache();
                                if app.autoeval {
                                    app.evaluate();
                                }
                            }
                            KeyCode::Char('s') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                app.toggle_bookmark();
                            }
                            KeyCode::Char('b') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                app.mode = AppMode::Bookmarks;
                                let n = app.bookmarks.len();
                                if n > 0 {
                                    app.list_state.select(Some(n - 1));
                                } else {
                                    app.list_state.select(Some(0));
                                }
                            }
                            KeyCode::Char('v') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                app.mode = AppMode::SnippetMenu;
                            }
                            KeyCode::Char('u') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                app.buffer.clear();
                                app.on_text_change();
                            }
                            KeyCode::Char('w') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                app.buffer.delete_word_back();
                                app.on_text_change();
                            }
                            KeyCode::Char('p') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                if let Some(prev) = app.history.prev(&app.buffer.to_command(false)) {
                                    app.buffer = TextBuffer::from_str(&prev);
                                    app.check_bookmarked();
                                    app.eval_output.is_stale = true;
                                    if app.autoeval {
                                        app.evaluate();
                                    }
                                }
                            }
                            KeyCode::Char('n') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                if let Some(next) = app.history.next() {
                                    app.buffer = TextBuffer::from_str(&next);
                                    app.check_bookmarked();
                                    app.eval_output.is_stale = true;
                                    if app.autoeval {
                                        app.evaluate();
                                    }
                                }
                            }
                            KeyCode::Enter if key.modifiers.contains(KeyModifiers::ALT) => {
                                app.buffer.insert_newline();
                                app.on_text_change();
                            }
                            KeyCode::Enter => {
                                app.evaluate_and_maybe_save_history();
                            }
                            KeyCode::Backspace => {
                                app.buffer.delete_char_back();
                                app.on_text_change();
                            }
                            KeyCode::Delete => {
                                app.buffer.delete_char_forward();
                                app.on_text_change();
                            }
                            KeyCode::Left => {
                                app.buffer.move_left();
                            }
                            KeyCode::Right => {
                                app.buffer.move_right();
                            }
                            KeyCode::Up => {
                                app.buffer.move_up();
                            }
                            KeyCode::Down => {
                                app.buffer.move_down();
                            }
                            KeyCode::Home => {
                                app.buffer.move_home();
                            }
                            KeyCode::End => {
                                app.buffer.move_end();
                            }
                            KeyCode::Char(c) => {
                                if key.modifiers.is_empty() || key.modifiers == KeyModifiers::SHIFT {
                                    app.buffer.insert_char(c);
                                    app.on_text_change();
                                }
                            }
                            _ => {}
                        }
                    }
                    AppMode::Help => {
                        match key.code {
                            KeyCode::F(1) | KeyCode::Esc => {
                                app.mode = AppMode::Normal;
