                            KeyCode::Enter => {
                                let idx = app.list_state.selected().unwrap_or(0);
                                let n = app.history.entries.len();
                                if idx < n {
                                    let entry = app.history.entries[idx].clone();
                                    app.buffer = TextBuffer::from_str(&entry);
                                    app.mode = AppMode::Normal;
