                                }
                            }
                            _ => {
                                app.mode = AppMode::Normal;
                            }
                        }
                    }
                    AppMode::OutputViewerMenu => {
                        match key.code {
                            KeyCode::Esc => {
                                app.mode = AppMode::Normal;
                            }
                            KeyCode::Char(c) => {
                                let key_str = c.to_string();
                                if let Some(viewers) = &app.config.output_viewers.clone() {
                                    if let Some(viewer_cmd) = viewers.get(&key_str) {
                                        let viewer_cmd = viewer_cmd.clone();
                                        let output = app.eval_output.stdout.clone();
                                        app.mode = AppMode::Normal;
                                        run_external_command(&viewer_cmd, "", &output);
                                    } else {
                                        app.mode = AppMode::Normal;
                                    }
                                } else {
                                    app.mode = AppMode::Normal;
                                }
                            }
                            _ => {
                                app.mode = AppMode::Normal;
                            }
                        }
                    }
                }
            }
            Event::Resize(_, _) => {
                // Will redraw on next iteration
            }
            _ => {}
        }
    }
