                        cfg['help_viewers'][hk.strip("'")] = hv
                elif k == 'output_viewers':
                    cfg['output_viewers'] = {}
                    for ok, ov in v.items():
                        cfg['output_viewers'][ok.strip("'")] = ov
                else:
                    cfg[k] = v
        except Exception:
            pass
    return cfg


def load_history() -> List[str]:
    if HISTORY_FILE.exists():
        try:
            lines = HISTORY_FILE.read_text().splitlines()
            return [l for l in lines if l]
        except Exception:
