def save_bookmarks(bookmarks: List[str]):
    try:
        CONFIG_DIR.mkdir(parents=True, exist_ok=True)
        BOOKMARKS_FILE.write_text('\n'.join(bookmarks))
    except Exception:
        pass


def run_command(env: List[str], cmd: str, timeout_ms: int) -> Tuple[str, str]:
    """Run command and return (stdout, stderr)"""
    if not cmd.strip():
        return '', ''
    if not env:
        return '', 'No eval environment configured'

    try:
        proc = subprocess.Popen(
            env + [cmd],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )
        try:
            stdout, stderr = proc.communicate(timeout=timeout_ms / 1000.0)
            return stdout.decode('utf-8', errors='replace'), stderr.decode('utf-8', errors='replace')
        except subprocess.TimeoutExpired:
            proc.kill()
            proc.communicate()
            return '', 'Command timed out'
    except Exception as e:
        return '', f'Error: {e}'


def build_command_from_lines(lines: List[str], raw: bool = False) -> str:
    """Build command filtering # lines and joining"""
    filtered = [l for l in lines if not l.lstrip().startswith('#')]
    if raw:
        return '\n'.join(filtered)
    else:
        return ' '.join(filtered)


class TextBuffer:
    def __init__(self, text: str = ''):
        if text:
            self.lines = text.split('\n')
        else:
            self.lines = ['']
        self.row = len(self.lines) - 1
        self.col = len(self.lines[self.row])

    def to_raw(self) -> str:
        return '\n'.join(self.lines)

    def to_command(self, raw: bool = False) -> str:
        return build_command_from_lines(self.lines, raw)

    def insert_char(self, ch: str):
        line = self.lines[self.row]
        self.lines[self.row] = line[:self.col] + ch + line[self.col:]
        self.col += 1

    def insert_newline(self):
        line = self.lines[self.row]
        rest = line[self.col:]
        self.lines[self.row] = line[:self.col]
        self.lines.insert(self.row + 1, rest)
        self.row += 1
        self.col = 0

    def backspace(self):
        if self.col > 0:
            line = self.lines[self.row]
            self.lines[self.row] = line[:self.col-1] + line[self.col:]
            self.col -= 1
        elif self.row > 0:
            prev_len = len(self.lines[self.row - 1])
            self.lines[self.row - 1] += self.lines[self.row]
            del self.lines[self.row]
            self.row -= 1
            self.col = prev_len

    def delete_forward(self):
        line = self.lines[self.row]
        if self.col < len(line):
            self.lines[self.row] = line[:self.col] + line[self.col+1:]
        elif self.row + 1 < len(self.lines):
            self.lines[self.row] += self.lines[self.row + 1]
            del self.lines[self.row + 1]

    def move_left(self):
        if self.col > 0:
            self.col -= 1
        elif self.row > 0:
            self.row -= 1
            self.col = len(self.lines[self.row])

    def move_right(self):
        line = self.lines[self.row]
        if self.col < len(line):
            self.col += 1
        elif self.row + 1 < len(self.lines):
            self.row += 1
            self.col = 0

    def move_home(self):
        self.col = 0

    def move_end(self):
        self.col = len(self.lines[self.row])

    def move_up(self):
        if self.row > 0:
            self.row -= 1
            self.col = min(self.col, len(self.lines[self.row]))

    def move_down(self):
        if self.row + 1 < len(self.lines):
            self.row += 1
            self.col = min(self.col, len(self.lines[self.row]))

    def delete_word_back(self):
        line = self.lines[self.row]
        if self.col == 0:
            if self.row > 0:
                self.backspace()
            return
        # Skip trailing spaces
        pos = self.col
        while pos > 0 and line[pos-1] == ' ':
            pos -= 1
        # Delete word
        while pos > 0 and line[pos-1] != ' ':
            pos -= 1
        self.lines[self.row] = line[:pos] + line[self.col:]
        self.col = pos

    def clear(self):
        self.lines = ['']
        self.row = 0
        self.col = 0

    def char_at_cursor(self) -> Optional[str]:
        line = self.lines[self.row]
        if self.col < len(line):
            return line[self.col]
        return None

    def abs_cursor_pos(self) -> int:
        pos = 0
        for i, line in enumerate(self.lines):
            if i == self.row:
                pos += self.col
                break
            pos += len(line) + 1  # +1 for newline
        return pos

    def word_at_cursor(self) -> str:
        line = self.lines[self.row]
        if not line:
            return ''
        col = min(self.col, len(line) - 1) if line else 0
        start = col
        end = col
        while start > 0 and line[start-1] not in (' ', '|', '<', '>'):
            start -= 1
        while end < len(line) and line[end] not in (' ', '|', '<', '>'):
            end += 1
        return line[start:end]

    def get_first_word_of_current_line(self) -> str:
        line = self.lines[self.row]
        parts = line.split()
        if parts:
            return parts[0]
        return ''


class App:
    def __init__(self, config: dict, initial_text: Optional[str], raw_mode: bool,
                 out_file: Optional[str], no_isolation: bool):
        self.config = config
        self.raw_mode = raw_mode
        self.out_file = out_file
        self.no_isolation = no_isolation

        self.buf = TextBuffer(initial_text or '')
        self.autoeval = config['autoeval_mode_default']
        self.paranoid = config['paranoid_history_mode_default']

        self.history = load_history()
        self.history_nav_idx = None  # None = at current/new position
        self.bookmarks = load_bookmarks()

        # Output
        self.stdout_lines = []
        self.stderr_lines = []
        self.output_stale = True

        # Cache
        self.cache_active = False
        self.cache_prefix = None
        self.cache_output = None

        # Bookmark state
        self.is_bookmarked = self._check_bookmarked()

        # Mode: 'normal', 'help', 'history', 'bookmarks', 'snippets', 'help_viewer', 'output_viewer'
        self.mode = 'normal'

        # List selection for history/bookmarks panels
        # For history: sel_idx is index into self.history (0=oldest)
        # Displayed newest at bottom, so sel = len-1 initially
        self.list_sel = 0

        # Initial evaluate
        if self.autoeval and self.buf.to_command().strip():
            self._evaluate()

    def _check_bookmarked(self) -> bool:
        cmd = self.buf.to_command(False)
        return cmd in self.bookmarks

    def _filter_cmd(self) -> str:
        """Build the command for eval, handling caching"""
        lines = self.buf.lines
        filtered = [l for l in lines if not l.lstrip().startswith('#')]
        joined = ' '.join(filtered)

        if self.cache_active and self.cache_prefix is not None and self.cache_output is not None:
            # Find where the pipe is in joined command
            # The cache was set at the first | that comes after the cached prefix
            # The suffix is everything from the pipe onward in the current command
            # We use: printf '%s' <cached_output> | <suffix>

            # Find first pipe position in joined
            pipe_pos = joined.find('|')
            if pipe_pos >= 0:
                suffix = joined[pipe_pos:]  # includes the | 
                # Use cached output as stdin for suffix
                # We need to pipe cached_output into the suffix command
                escaped = self.cache_output.replace("'", "'\\''")
                return f"printf '%s' '{escaped}' {suffix}"

        return joined

    def _evaluate(self):
        cmd = self._filter_cmd()
        if not cmd.strip():
            self.stdout_lines = []
            self.stderr_lines = []
            self.output_stale = False
            return

        env = self.config['eval_environment']
        timeout_ms = self.config['cmd_timeout_millis']

        stdout, stderr = run_command(env, cmd, timeout_ms)

        # Remove trailing newline
        if stdout.endswith('\n'):
            stdout = stdout[:-1]
        if stderr.endswith('\n'):
            stderr = stderr[:-1]

        self.stdout_lines = stdout.split('\n') if stdout else []
        self.stderr_lines = stderr.split('\n') if stderr else []
        self.output_stale = False

    def on_text_change(self):
        self.is_bookmarked = self._check_bookmarked()
        self.output_stale = True
        # Invalidate cache if prefix changed
        if self.cache_active and self.cache_prefix is not None:
            current_filtered = ' '.join(l for l in self.buf.lines if not l.lstrip().startswith('#'))
            if not current_filtered.startswith(self.cache_prefix):
                self.cache_active = False
                self.cache_prefix = None
                self.cache_output = None

        if self.autoeval:
            self._evaluate()
            if self.paranoid and not self.stderr_lines:
                cmd = self.buf.to_command(self.raw_mode)
                if cmd.strip():
                    self._push_history(cmd)

    def _push_history(self, cmd: str):
        if not cmd.strip():
            return
        if self.history and self.history[-1] == cmd:
            return
        self.history.append(cmd)
        max_size = self.config['history_size']
        if len(self.history) > max_size:
            self.history = self.history[-max_size:]
        self.history_nav_idx = None
        save_history(self.history)

    def evaluate_and_save(self):
        self._evaluate()
        cmd = self.buf.to_command(self.raw_mode)
        if cmd.strip():
            self._push_history(cmd)

    def toggle_bookmark(self):
        cmd = self.buf.to_command(False)
        if not cmd.strip():
            return
        if self.is_bookmarked:
            self.bookmarks = [b for b in self.bookmarks if b != cmd]
            self.is_bookmarked = False
        else:
            self.bookmarks.append(cmd)
            self.is_bookmarked = True
        save_bookmarks(self.bookmarks)

    def toggle_cache(self):
        if self.cache_active:
            self.cache_active = False
            self.cache_prefix = None
            self.cache_output = None
            return

        # Check if cursor is on |
        ch = self.buf.char_at_cursor()
        if ch == '|':
            # Get prefix up to cursor
            full = self.buf.to_raw()
            pos = self.buf.abs_cursor_pos()
            prefix_raw = full[:pos]
            filtered_prefix = ' '.join(l for l in prefix_raw.split('\n') 
                                       if not l.lstrip().startswith('#'))

            env = self.config['eval_environment']
            timeout_ms = self.config['cmd_timeout_millis']
            stdout, _ = run_command(env, filtered_prefix, timeout_ms)

            if stdout.endswith('\n'):
                stdout = stdout[:-1]

            self.cache_prefix = filtered_prefix
            self.cache_output = stdout
            self.cache_active = True

    def history_prev(self):
        if not self.history:
            return
        if self.history_nav_idx is None:
            self.history_nav_idx = len(self.history) - 1
        elif self.history_nav_idx > 0:
            self.history_nav_idx -= 1

        entry = self.history[self.history_nav_idx]
        self.buf = TextBuffer(entry)
        self.is_bookmarked = self._check_bookmarked()
        self.output_stale = True
        if self.autoeval:
            self._evaluate()

    def history_next(self):
        if self.history_nav_idx is None:
            return
        self.history_nav_idx += 1
        if self.history_nav_idx >= len(self.history):
            self.history_nav_idx = None
            self.buf = TextBuffer('')
        else:
            entry = self.history[self.history_nav_idx]
            self.buf = TextBuffer(entry)
        self.is_bookmarked = self._check_bookmarked()
        self.output_stale = True
        if self.autoeval:
            self._evaluate()

    def get_help_word(self) -> str:
        word = self.buf.word_at_cursor()
        if not word:
            word = self.buf.get_first_word_of_current_line()
        return word

    def insert_snippet(self, key: str):
        snippets = self.config.get('snippets', {})
        if key in snippets:
            snippet = snippets[key]
            if '||' in snippet:
                before, after = snippet.split('||', 1)
                for ch in before:
                    if ch == '\n':
                        self.buf.insert_newline()
                    else:
                        self.buf.insert_char(ch)
                saved_row = self.buf.row
                saved_col = self.buf.col
                for ch in after:
                    if ch == '\n':
                        self.buf.insert_newline()
                    else:
                        self.buf.insert_char(ch)
                self.buf.row = saved_row
                self.buf.col = saved_col
            else:
                for ch in snippet:
                    if ch == '\n':
                        self.buf.insert_newline()
                    else:
                        self.buf.insert_char(ch)
            self.on_text_change()


# ---- Drawing functions ----

def draw_box_top(stdscr, y: int, x: int, width: int, title: str):
    """Draw top border with title. Format: ' ┌ TITLE ────┐'"""
    # x is where the leading space is
    # box starts at x+1 (┌), ends at x+width-1 (┐)
    line = ' ┌ ' + title + ' '
    dashes = width - len(line) - 1  # -1 for closing ┐
    if dashes < 0:
        dashes = 0
    line += '─' * dashes + '┐'
    try:
        stdscr.addstr(y, x, line)
    except curses.error:
        pass


def draw_box_top_no_space(stdscr, y: int, x: int, width: int, title: str):
    """Draw top border without leading space. Format: '┌ TITLE ────┐'"""
    line = '┌ ' + title + ' '
    dashes = width - len(line) - 1
    if dashes < 0:
        dashes = 0
    line += '─' * dashes + '┐'
    try:
        stdscr.addstr(y, x, line)
    except curses.error:
        pass


def draw_box_bottom(stdscr, y: int, x: int, width: int, help_text: bool = False):
    """Draw bottom border. If help_text, include 'Help: F1──'"""
    if help_text:
        # ' └──────────────────────────────────────────────────────────────────Help: F1──┘'
        help_str = 'Help: F1'
        trailer = '──┘'
        prefix = ' └'
        dashes = width - len(prefix) - len(help_str) - len(trailer)
        if dashes < 0:
            dashes = 0
        line = prefix + '─' * dashes + help_str + trailer
    else:
        line = ' └' + '─' * (width - 3) + '┘'
    try:
        stdscr.addstr(y, x, line)
    except curses.error:
        pass


def draw_box_bottom_no_space(stdscr, y: int, x: int, width: int, help_text: bool = False):
    """Draw bottom border without leading space."""
    if help_text:
        help_str = 'Help: F1'
        trailer = '──┘'
        prefix = '└'
        dashes = width - len(prefix) - len(help_str) - len(trailer)
        if dashes < 0:
            dashes = 0
        line = prefix + '─' * dashes + help_str + trailer
    else:
        line = '└' + '─' * (width - 2) + '┘'
    try:
        stdscr.addstr(y, x, line)
    except curses.error:
        pass


def draw_box_row(stdscr, y: int, x: int, width: int, content: str = ''):
    """Draw a content row of a box. Format: ' │ content ... │'"""
    inner_width = width - 3  # -1 for space, -2 for borders
    content_padded = content[:inner_width].ljust(inner_width)
    line = ' │' + content_padded + '│'
    try:
        stdscr.addstr(y, x, line)
    except curses.error:
        pass


def draw_box_row_no_space(stdscr, y: int, x: int, width: int, content: str = ''):
    """Draw content row without leading space. '│ content │'"""
    inner_width = width - 2  # -2 for borders
    content_padded = content[:inner_width].ljust(inner_width)
    line = '│' + content_padded + '│'
    try:
        stdscr.addstr(y, x, line)
    except curses.error:
        pass


def truncate_to_width(s: str, w: int) -> str:
    if len(s) <= w:
        return s
    return s[:w]


def draw_main_view(stdscr, app: App, x: int, y: int, width: int, height: int):
    """Draw the main command + output view"""
    # Command box: rows y to y+2 (height=3)
    cmd_title = build_cmd_title(app)

    # Determine if we have stderr
    has_stderr = bool(app.stderr_lines)

    # Command box
    if x == 0:
        draw_box_top(stdscr, y, x, width, cmd_title)
    else:
        draw_box_top_no_space(stdscr, y, x, width, cmd_title)

    # Content row(s) - show buffer lines (max 1 displayed in box height=1)
    cmd_inner_width = width - (3 if x == 0 else 2)
    num_cmd_rows = min(len(app.buf.lines), 1)  # Always 1 row visible

    for i in range(1):  # Command box inner height = 1
        content = ''
        if i < len(app.buf.lines):
            content = app.buf.lines[i]
        if x == 0:
            draw_box_row(stdscr, y + 1 + i, x, width, content)
        else:
            draw_box_row_no_space(stdscr, y + 1 + i, x, width, content)

    if x == 0:
        draw_box_bottom(stdscr, y + 2, x, width)
    else:
        draw_box_bottom_no_space(stdscr, y + 2, x, width)

    # Calculate output areas
    remaining_height = height - 3  # subtract command box

    if has_stderr:
        out_height = remaining_height // 2
        err_height = remaining_height - out_height
    else:
        out_height = remaining_height
        err_height = 0

    out_title = ' Output [+] ' if app.output_stale else ' Output '
    out_title = out_title.strip()

    # Output box
    out_y = y + 3
    if x == 0:
        draw_box_top(stdscr, out_y, x, width, out_title)
    else:
        draw_box_top_no_space(stdscr, out_y, x, width, out_title)

    out_inner_rows = out_height - 2
    for i in range(out_inner_rows):
        content = ''
        if i < len(app.stdout_lines):
            content = app.stdout_lines[i]
        if x == 0:
            draw_box_row(stdscr, out_y + 1 + i, x, width, content)
        else:
            draw_box_row_no_space(stdscr, out_y + 1 + i, x, width, content)

    out_bottom_y = out_y + out_height - 1
    if has_stderr:
        if x == 0:
            draw_box_bottom(stdscr, out_bottom_y, x, width, False)
        else:
            draw_box_bottom_no_space(stdscr, out_bottom_y, x, width, False)
    else:
        if x == 0:
            draw_box_bottom(stdscr, out_bottom_y, x, width, True)
        else:
            draw_box_bottom_no_space(stdscr, out_bottom_y, x, width, True)

    # Stderr box if needed
    if has_stderr:
        err_y = out_y + out_height
        if x == 0:
            draw_box_top(stdscr, err_y, x, width, 'Stderr')
        else:
            draw_box_top_no_space(stdscr, err_y, x, width, 'Stderr')

        err_inner_rows = err_height - 2
        for i in range(err_inner_rows):
            content = ''
            if i < len(app.stderr_lines):
                content = app.stderr_lines[i]
            if x == 0:
                draw_box_row(stdscr, err_y + 1 + i, x, width, content)
            else:
                draw_box_row_no_space(stdscr, err_y + 1 + i, x, width, content)

        err_bottom_y = err_y + err_height - 1
        if x == 0:
            draw_box_bottom(stdscr, err_bottom_y, x, width, True)
        else:
            draw_box_bottom_no_space(stdscr, err_bottom_y, x, width, True)

    # Set cursor position in command box (only if x==0, primary view)
    if x == 0:
        cursor_x = x + 2 + app.buf.col  # +2 for ' │'
        cursor_y = y + 1 + app.buf.row
        try:
            stdscr.move(cursor_y, cursor_x)
        except curses.error:
            pass


def build_cmd_title(app: App) -> str:
    parts = ['Command']
    if app.is_bookmarked:
        parts.append('Bookmarked')
    if app.autoeval:
        parts.append('Autoeval')
    if app.cache_active:
        parts.append('Caching')
    if app.paranoid:
        parts.append('Paranoid')
    return ' ['.join(parts[0:1]) + (''.join(f' [{p}]' for p in parts[1:]))


def draw_help_panel(stdscr, y: int, x: int, width: int, height: int):
    """Draw the full-screen help panel"""
    draw_box_top(stdscr, y, x, width, 'Help')

    help_lines = [
        'F1         Show/hide help',
        'F2         Toggle autoeval',
        'F3         Toggle Paranoid history (fills up history in autoeval)',
        'F4         Show/hide history',
        'Ctrl+B     Show/hide bookmarks',
        'F5         Open helpviewer',
        'F6         Open outputviewer',
        'F7         When the cursor is on a `|` symbol, cache the output of everythin',
        'Ctrl+S     Save bookmark',
        'Alt+Return Newline',
        'Ctrl+U     Clear Command',
        'Ctrl+P     Previous in history',
        'Ctrl+N     Next in history',
        'Ctrl+V     Insert snippet (press corresponding key to choose)',
        '',
        'disable a line by starting it with a #',
        'this will simply exclude the line from the executed command.',
        '',
        'Config file is in',
        '~/.config/pipr/pipr.toml',
    ]

    inner_rows = height - 2
    for i in range(inner_rows):
        content = ''
        if i < len(help_lines):
            content = help_lines[i]
        draw_box_row(stdscr, y + 1 + i, x, width, content)

    draw_box_bottom(stdscr, y + height - 1, x, width, True)


def draw_list_panel(stdscr, y: int, x: int, width: int, height: int,
                    title: str, items: List[str], sel_idx: int):
    """Draw history or bookmarks panel"""
    draw_box_top(stdscr, y, x, width, title)

    inner_rows = height - 2
    inner_width = width - 3  # for ' │...│'

    for i in range(inner_rows):
        # Calculate which item to show
        item_idx = i
        content = ''
        if item_idx < len(items):
            item = items[item_idx]
            item_display = item.replace('\n', ' ↵ ')
            if item_idx == sel_idx:
                prefix = '>>'
            else:
                prefix = '  '
            content = prefix + item_display
        draw_box_row(stdscr, y + 1 + i, x, width, content)

    draw_box_bottom(stdscr, y + height - 1, x, width, False)


def draw_menu_popup(stdscr, y: int, x: int, width: int, height: int,
                    title: str, items: List[Tuple[str, str]]):
    """Draw popup menu (snippets, help viewers, output viewers)"""
    draw_box_top_no_space(stdscr, y, x, width, title)

    inner_rows = height - 2
    for i in range(inner_rows):
        content = ''
        if i < len(items):
            key, value = items[i]
            content = f'{key}: {value}'
        draw_box_row_no_space(stdscr, y + 1 + i, x, width, content)

    draw_box_bottom_no_space(stdscr, y + height - 1, x, width, False)


def draw_screen(stdscr, app: App):
    stdscr.clear()
    height, width = stdscr.getmaxyx()

    # Row 0 is always blank
    # Visible content starts at row 1

    if app.mode == 'help':
        # Full-screen help panel
        panel_height = height - 1  # rows 1..height-1
        draw_help_panel(stdscr, 1, 0, width, panel_height)
        # Bottom "Help: F1" bar is inside the panel's bottom border

    elif app.mode in ('history', 'bookmarks'):
        panel_height = 10

        if app.mode == 'history':
            title = 'History'
            # Display history newest at bottom, sel_idx = index into reversed list
            # Actually we display in order with >> marker
            items = app.history[:]
            sel = app.list_sel
        else:
            title = 'Bookmarks'
            items = app.bookmarks[:]
            sel = app.list_sel

        draw_list_panel(stdscr, 1, 0, width, panel_height, title, items, sel)

        # Bottom help text (standalone, not in box)
        try:
            help_str = 'Help: F1'
            stdscr.addstr(height - 1, width - len(help_str) - 1, help_str)
        except curses.error:
            pass

    elif app.mode in ('snippets', 'help_viewer', 'output_viewer'):
        # Popup on left, main view on right
        popup_width = 32  # with leading space = 31 inner
        main_x = popup_width
        main_width = width - popup_width

        # Build menu items
        if app.mode == 'snippets':
            title = 'Open in'
            items = []
            for k, v in sorted(app.config.get('snippets', {}).items()):
                display = v.replace('||', '')
                items.append((k, display))
        elif app.mode == 'help_viewer':
            title = 'Open in'
            word = app.get_help_word()
            items = []
            for k, v in sorted(app.config.get('help_viewers', {}).items()):
                display = v.replace('??', word)
                items.append((k, display))
        else:  # output_viewer
            title = 'Open in'
            items = []
            for k, v in sorted(app.config.get('output_viewers', {}).items()):
                items.append((k, v))

        popup_height = height - 1
        # The popup starts at y=1
        draw_menu_popup(stdscr, 1, 1, popup_width - 1, popup_height, title, items)

        # Main view on the right
        # starts at x=popup_width (no leading space, since left side has right border)
        # Actually in the original the right box shares the right border of left box
        # ' ┌ Open in ────────────────────┐┌ Command [Autoeval] ─────────────────────────┐'
        # The popup box goes from col 1 to col 31 (width=31)
        # The main box goes from col 31 to col 78 (width=48)
        # But col 31 is '┐' of popup AND '┌' of main... they share no space

        # Let me re-examine:
        # ' ┌ Open in ────────────────────┐┌ Command [Autoeval] ─────────────────────────┐'
        # ' '=col0, '┌'=col1, ... '┐'=col31, '┌'=col32 ... '┐'=col78
        # So popup: cols 0-31 (width 32, with leading space = 32)
        # Main: cols 32-78 (width 47)

        # Actually main x=32 without leading space, width=47
        draw_main_view_right(stdscr, app, 32, 1, 47, height - 1)

    else:  # normal mode
        # Full width main view
        draw_main_view(stdscr, app, 0, 1, width, height - 1)


def draw_main_view_right(stdscr, app: App, x: int, y: int, width: int, height: int):
    """Draw the main view for the right panel in popup mode"""
    cmd_title = build_cmd_title(app)
    has_stderr = bool(app.stderr_lines)

    # Command box
    draw_box_top_no_space(stdscr, y, x, width, cmd_title)

    inner_width = width - 2
    content = app.buf.lines[0] if app.buf.lines else ''
    draw_box_row_no_space(stdscr, y + 1, x, width, content)
    draw_box_bottom_no_space(stdscr, y + 2, x, width, False)

    # Output box
    out_title = 'Output [+]' if app.output_stale else 'Output'
    remaining = height - 3

    if has_stderr:
        out_height = remaining // 2
        err_height = remaining - out_height
    else:
        out_height = remaining
        err_height = 0

    draw_box_top_no_space(stdscr, y + 3, x, width, out_title)

    out_inner_rows = out_height - 2
    for i in range(out_inner_rows):
        content = ''
        if i < len(app.stdout_lines):
            content = app.stdout_lines[i]
        draw_box_row_no_space(stdscr, y + 4 + i, x, width, content)

    out_bottom_y = y + 3 + out_height - 1
    if has_stderr:
        draw_box_bottom_no_space(stdscr, out_bottom_y, x, width, False)
    else:
        draw_box_bottom_no_space(stdscr, out_bottom_y, x, width, True)

    if has_stderr:
        err_y = y + 3 + out_height
        draw_box_top_no_space(stdscr, err_y, x, width, 'Stderr')
        err_inner_rows = err_height - 2
        for i in range(err_inner_rows):
            content = ''
            if i < len(app.stderr_lines):
                content = app.stderr_lines[i]
            draw_box_row_no_space(stdscr, err_y + 1 + i, x, width, content)
        draw_box_bottom_no_space(stdscr, err_y + err_height - 1, x, width, True)


def run_external(cmd: str, stdin_data: str = ''):
    """Run external command, suspending curses"""
    curses.endwin()
    if stdin_data:
        proc = subprocess.Popen(['sh', '-c', cmd], stdin=subprocess.PIPE)
        proc.communicate(input=stdin_data.encode())
    else:
        proc = subprocess.Popen(['sh', '-c', cmd])
        proc.wait()
    # Re-init
    curses.doupdate()


def main_loop(stdscr, app: App):
    curses.curs_set(1)
    stdscr.keypad(True)
    stdscr.timeout(100)

    # Enable keypad for function keys
    stdscr.nodelay(False)
    stdscr.timeout(-1)

    # Set ESC delay shorter
    curses.set_escdelay(25)

    while True:
        draw_screen(stdscr, app)
        stdscr.refresh()

        try:
            ch = stdscr.get_wch()
        except curses.error:
            continue

        if isinstance(ch, str):
            ch_int = ord(ch)
        else:
            ch_int = ch

        if app.mode == 'normal':
            handle_normal_key(stdscr, app, ch, ch_int)
        elif app.mode == 'help':
            if ch_int in (curses.KEY_F1, 27):  # F1 or Escape
                app.mode = 'normal'
        elif app.mode == 'history':
            if handle_list_key(stdscr, app, ch, ch_int, 'history') == 'quit':
                return
        elif app.mode == 'bookmarks':
            if handle_list_key(stdscr, app, ch, ch_int, 'bookmarks') == 'quit':
                return
        elif app.mode in ('snippets', 'help_viewer', 'output_viewer'):
            handle_menu_key(stdscr, app, ch, ch_int)

        # Check if we should quit (mode changed to 'quit')
        if app.mode == 'quit':
            return


def handle_normal_key(stdscr, app: App, ch, ch_int: int):
    if ch_int == 27:  # Escape
        app.mode = 'quit'
        return

    if ch_int == curses.KEY_F1:
        app.mode = 'help'
    elif ch_int == curses.KEY_F2:
        app.autoeval = not app.autoeval
        if app.autoeval:
            app._evaluate()
    elif ch_int == curses.KEY_F3:
        app.paranoid = not app.paranoid
    elif ch_int == curses.KEY_F4:
        app.mode = 'history'
        n = len(app.history)
        app.list_sel = max(0, n - 1)
    elif ch_int == curses.KEY_F5:
        app.mode = 'help_viewer'
    elif ch_int == curses.KEY_F6:
        app.mode = 'output_viewer'
    elif ch_int == curses.KEY_F7:
        app.toggle_cache()
        if app.autoeval:
            app._evaluate()
    elif ch_int == 19:  # Ctrl+S
        app.toggle_bookmark()
    elif ch_int == 2:  # Ctrl+B
        app.mode = 'bookmarks'
        n = len(app.bookmarks)
        app.list_sel = max(0, n - 1)
    elif ch_int == 22:  # Ctrl+V
        app.mode = 'snippets'
    elif ch_int == 21:  # Ctrl+U
        app.buf.clear()
        app.on_text_change()
    elif ch_int == 23:  # Ctrl+W
        app.buf.delete_word_back()
        app.on_text_change()
    elif ch_int == 16:  # Ctrl+P
        app.history_prev()
    elif ch_int == 14:  # Ctrl+N
        app.history_next()
    elif ch == '\n' or ch_int == 10:  # Enter (regular)
        app.evaluate_and_save()
    elif ch_int == curses.KEY_ENTER:
        app.evaluate_and_save()
    elif isinstance(ch, str) and ch == '\x0a':  # Alt+Enter - need special handling
        app.buf.insert_newline()
        app.on_text_change()
    elif ch_int == curses.KEY_BACKSPACE or ch_int == 127 or ch_int == 8:
        app.buf.backspace()
        app.on_text_change()
    elif ch_int == curses.KEY_DC:
        app.buf.delete_forward()
        app.on_text_change()
    elif ch_int == curses.KEY_LEFT:
        app.buf.move_left()
    elif ch_int == curses.KEY_RIGHT:
        app.buf.move_right()
    elif ch_int == curses.KEY_UP:
        app.buf.move_up()
    elif ch_int == curses.KEY_DOWN:
        app.buf.move_down()
    elif ch_int == curses.KEY_HOME:
        app.buf.move_home()
    elif ch_int == curses.KEY_END:
        app.buf.move_end()
    elif ch_int == curses.KEY_RESIZE:
        pass  # Will redraw
    elif isinstance(ch, str) and len(ch) == 1 and ch_int >= 32:
        app.buf.insert_char(ch)
        app.on_text_change()


def handle_list_key(stdscr, app: App, ch, ch_int: int, list_type: str):
    items = app.history if list_type == 'history' else app.bookmarks
    n = len(items)

    if ch_int == 27:  # Escape
        app.mode = 'normal'
    elif ch_int == curses.KEY_F4 and list_type == 'history':
        app.mode = 'normal'
    elif ch_int == 2 and list_type == 'bookmarks':  # Ctrl+B
        app.mode = 'normal'
    elif ch_int == curses.KEY_UP:
        if app.list_sel > 0:
            app.list_sel -= 1
    elif ch_int == curses.KEY_DOWN:
        if app.list_sel < n - 1:
            app.list_sel += 1
    elif ch_int == 16:  # Ctrl+P
        if app.list_sel > 0:
            app.list_sel -= 1
    elif ch_int == 14:  # Ctrl+N
        if app.list_sel < n - 1:
            app.list_sel += 1
    elif ch_int in (curses.KEY_ENTER, 10, 13):  # Enter
        if 0 <= app.list_sel < n:
            entry = items[app.list_sel]
            app.buf = TextBuffer(entry)
            app.mode = 'normal'
            app.is_bookmarked = app._check_bookmarked()
            app.output_stale = True
            if app.autoeval:
                app._evaluate()
    elif ch_int == curses.KEY_DC:  # Delete key
        if list_type == 'bookmarks' and 0 <= app.list_sel < n:
            del app.bookmarks[app.list_sel]
            save_bookmarks(app.bookmarks)
            new_n = len(app.bookmarks)
            if new_n == 0:
                app.list_sel = 0
            else:
                app.list_sel = min(app.list_sel, new_n - 1)
            app.is_bookmarked = app._check_bookmarked()


def handle_menu_key(stdscr, app: App, ch, ch_int: int):
    if ch_int == 27:  # Escape
        app.mode = 'normal'
        return

    if not isinstance(ch, str):
        app.mode = 'normal'
        return

    key = ch

    if app.mode == 'snippets':
        app.mode = 'normal'
        app.insert_snippet(key)
    elif app.mode == 'help_viewer':
        viewers = app.config.get('help_viewers', {})
        if key in viewers:
            cmd_template = viewers[key]
            word = app.get_help_word()
            cmd = cmd_template.replace('??', word)
            app.mode = 'normal'
            run_external(cmd)
        else:
            app.mode = 'normal'
    elif app.mode == 'output_viewer':
        viewers = app.config.get('output_viewers', {})
        if key in viewers:
            cmd = viewers[key]
            stdout_data = '\n'.join(app.stdout_lines)
            app.mode = 'normal'
            run_external(cmd, stdout_data)
        else:
            app.mode = 'normal'


def setup_alt_enter(stdscr):
    """Try to handle Alt+Enter"""
    # In many terminals, Alt+Enter sends ESC followed by Enter
    # We handle this in the key reading loop
    pass


def run_tui(initial_text: Optional[str], raw_mode: bool, out_file: Optional[str], 
            no_isolation: bool):
    config = load_config()
    app = App(config, initial_text, raw_mode, out_file, no_isolation)

    def curses_main(stdscr):
        # Enable keypad and mouse
        stdscr.keypad(True)
        curses.noecho()
        curses.cbreak()

        # Try to handle Alt+Enter
        # We need to check for escape sequences
        stdscr.timeout(-1)

        main_loop_with_alt(stdscr, app)

    curses.wrapper(curses_main)
    return app


def main_loop_with_alt(stdscr, app: App):
    """Main loop with Alt+Enter support"""
    curses.curs_set(1)
    stdscr.keypad(True)

    # Set shorter escape delay to handle Alt sequences
    curses.set_escdelay(25)

    while True:
        draw_screen(stdscr, app)
        stdscr.refresh()

        try:
            ch = stdscr.get_wch()
        except curses.error:
            continue

        if isinstance(ch, str):
            ch_int = ord(ch)
        else:
            ch_int = ch

        # Handle escape sequences (Alt+key)
        if ch_int == 27:  # ESC
            # Check if it's Alt+something
            stdscr.timeout(50)  # Short timeout to check for next char
            try:
                next_ch = stdscr.get_wch()
                stdscr.timeout(-1)
                if isinstance(next_ch, str):
                    next_int = ord(next_ch)
                else:
                    next_int = next_ch

                # Alt+Enter
                if next_int in (10, 13, curses.KEY_ENTER):
                    if app.mode == 'normal':
                        app.buf.insert_newline()
                        app.on_text_change()
                    continue
                else:
                    # Just ESC (not Alt combo)
                    stdscr.timeout(-1)
                    # Process ESC normally
                    if app.mode == 'normal':
                        app.mode = 'quit'
                    elif app.mode == 'help':
                        app.mode = 'normal'
                    elif app.mode in ('history', 'bookmarks'):
                        app.mode = 'normal'
                    elif app.mode in ('snippets', 'help_viewer', 'output_viewer'):
                        app.mode = 'normal'

                    if app.mode == 'quit':
                        return
                    continue
            except curses.error:
                stdscr.timeout(-1)
                # Just ESC
                if app.mode == 'normal':
                    app.mode = 'quit'
                    return
                elif app.mode == 'help':
                    app.mode = 'normal'
                elif app.mode in ('history', 'bookmarks'):
                    app.mode = 'normal'
                elif app.mode in ('snippets', 'help_viewer', 'output_viewer'):
                    app.mode = 'normal'
                continue

        if app.mode == 'normal':
            handle_normal_key(stdscr, app, ch, ch_int)
        elif app.mode == 'help':
            if ch_int == curses.KEY_F1:
                app.mode = 'normal'
        elif app.mode == 'history':
            handle_list_key(stdscr, app, ch, ch_int, 'history')
        elif app.mode == 'bookmarks':
            handle_list_key(stdscr, app, ch, ch_int, 'bookmarks')
        elif app.mode in ('snippets', 'help_viewer', 'output_viewer'):
            handle_menu_key(stdscr, app, ch, ch_int)

        if app.mode == 'quit':
            return


