def print_usage(prog: str):
    print(f"""Usage: {prog} [options]

Options:
    -d, --default TEXT  text inserted into the textfield on startup
    -o, --out-file FILE write final command to file
        --in-file FILE  read initial command from file
        --config-reference 
                        print out the default configuration file
    -r, --raw-mode      keep linebreaks in finished command when closing
        --no-isolation  disable isolation. This will run the commands directly
                        on your system, without protection. Take care.
    -h, --help          print this help menu""")


def parse_args(args: List[str]):
    result = {
        'default': None,
        'out_file': None,
        'in_file': None,
        'config_reference': False,
        'raw_mode': False,
        'no_isolation': False,
        'help': False,
    }

    i = 0
    while i < len(args):
        arg = args[i]
        if arg in ('-d', '--default'):
            i += 1
            if i < len(args):
                result['default'] = args[i]
        elif arg in ('-o', '--out-file'):
            i += 1
            if i < len(args):
                result['out_file'] = args[i]
        elif arg == '--in-file':
            i += 1
            if i < len(args):
                result['in_file'] = args[i]
        elif arg == '--config-reference':
            result['config_reference'] = True
        elif arg in ('-r', '--raw-mode'):
            result['raw_mode'] = True
        elif arg == '--no-isolation':
            result['no_isolation'] = True
        elif arg in ('-h', '--help'):
            result['help'] = True
        i += 1

    return result


def check_bwrap() -> bool:
    """Check if bwrap is available"""
    try:
        result = subprocess.run(['which', 'bwrap'], capture_output=True)
        return result.returncode == 0
    except Exception:
        return False


def main():
    args = parse_args(sys.argv[1:])

    if args['help']:
        print_usage(sys.argv[0])
        return

    if args['config_reference']:
        print_config_reference()
        return

    no_isolation = args['no_isolation']

    if not no_isolation:
        if not check_bwrap():
            print("bubblewrap installation not found. Please make sure you have `bwrap` on your path, or supply --no-isolation to disable safe-mode", 
                  file=sys.stderr)
            sys.exit(1)

    # Get initial text
    initial_text = None
    if args['in_file']:
        try:
            content = Path(args['in_file']).read_text()
            initial_text = content.rstrip('\n')
        except Exception:
            pass
    elif args['default']:
        initial_text = args['default']

    raw_mode = args['raw_mode']
    out_file = args['out_file']

    # Run TUI
    config = load_config()
    app = App(config, initial_text, raw_mode, out_file, no_isolation)

    def curses_main(stdscr):
        curses.noecho()
        curses.cbreak()
        stdscr.keypad(True)
        curses.set_escdelay(25)
        main_loop_with_alt(stdscr, app)

    try:
        curses.wrapper(curses_main)
    except KeyboardInterrupt:
        pass

    # Write output
    final_cmd = app.buf.to_command(app.raw_mode)

    if out_file:
        try:
            Path(out_file).write_text(final_cmd)
        except Exception:
            pass

    # Run finish hook
    finish_hook = config.get('finish_hook')
    if finish_hook:
        try:
            proc = subprocess.Popen(['sh', '-c', finish_hook], stdin=subprocess.PIPE)
            proc.communicate(input=final_cmd.encode())
        except Exception:
            pass

    print(final_cmd)


if __name__ == '__main__':
    main()
