def load_config() -> dict:
    cfg = dict(DEFAULT_CONFIG)
    # Deep copy of nested dicts
    cfg['snippets'] = dict(DEFAULT_CONFIG['snippets'])
    cfg['help_viewers'] = dict(DEFAULT_CONFIG['help_viewers'])
    cfg['output_viewers'] = dict(DEFAULT_CONFIG['output_viewers'])
    cfg['eval_environment'] = list(DEFAULT_CONFIG['eval_environment'])

    if CONFIG_FILE.exists() and tomllib is not None:
        try:
            with open(CONFIG_FILE, 'rb') as f:
                file_cfg = tomllib.load(f)
            for k, v in file_cfg.items():
                if k == 'snippets':
