'h' = "?? --help | less"

[output_viewers]
'l' = "less"
"""


def parse_args(argv: List[str]) -> dict:
    result = {
        'default': None, 'out_file': None, 'in_file': None,
        'config_reference': False, 'raw_mode': False,
        'no_isolation': False, 'help': False,
    }
    i = 0
    while i < len(argv):
        a = argv[i]
        if a in ('-d', '--default') and i + 1 < len(argv):
            i += 1; result['default'] = argv[i]
        elif a in ('-o', '--out-file') and i + 1 < len(argv):
            i += 1; result['out_file'] = argv[i]
        elif a == '--in-file' and i + 1 < len(argv):
            i += 1; result['in_file'] = argv[i]
        elif a == '--config-reference':
            result['config_reference'] = True
        elif a in ('-r', '--raw-mode'):
            result['raw_mode'] = True
        elif a == '--no-isolation':
            result['no_isolation'] = True
        elif a in ('-h', '--help'):
            result['help'] = True
        i += 1
    return result


def print_usage(prog: str):
    print(f"Usage: {prog} [options]\n\nOptions:")
    print("    -d, --default TEXT  text inserted into the textfield on startup")
    print("    -o, --out-file FILE write final command to file")
    print("        --in-file FILE  read initial command from file")
    print("        --config-reference \n                        print out the default configuration file")
    print("    -r, --raw-mode      keep linebreaks in finished command when closing")
    print("        --no-isolation  disable isolation. This will run the commands directly")
    print("                        on your system, without protection. Take care.")
    print("    -h, --help          print this help menu")


def check_bwrap() -> bool:
    try:
        return subprocess.run(['which', 'bwrap'], capture_output=True).returncode == 0
    except Exception:
        return False


def main():
    args = parse_args(sys.argv[1:])

    if args['help']:
        print_usage(sys.argv[0])
        return

    if args['config_reference']:
        print(DEFAULT_CONFIG_REFERENCE)
        return

    if not args['no_isolation']:
        if not check_bwrap():
            print("bubblewrap installation not found. Please make sure you have `bwrap` on your path, "
                  "or supply --no-isolation to disable safe-mode", file=sys.stderr)
            sys.exit(1)

    initial_text = None
    if args['in_file']:
        try:
            initial_text = Path(args['in_file']).read_text().rstrip('\n')
        except Exception:
            pass
    elif args['default']:
        initial_text = args['default']

    config = load_config()
    app = App(config, initial_text, args['raw_mode'], args['out_file'], args['no_isolation'])

    try:
        curses.wrapper(lambda stdscr: main_loop(stdscr, app))
    except KeyboardInterrupt:
        pass

    final_cmd = app.buf.to_command(app.raw_mode)

    if args['out_file']:
        try:
            Path(args['out_file']).write_text(final_cmd)
        except Exception:
            pass

    finish_hook = config.get('finish_hook')
    if finish_hook:
        try:
            proc = subprocess.Popen(['sh', '-c', finish_hook], stdin=subprocess.PIPE)
            proc.communicate(input=final_cmd.encode())
        except Exception:
            pass

    print(final_cmd)


if __name__ == '__main__':
    main()
