#!/usr/bin/env python3
"""
Pipr - Interactive pipeline builder TUI
"""

import curses
import os
import sys
import subprocess
import time
from pathlib import Path
from typing import Optional, List, Tuple, Dict

try:
    import tomllib
except ImportError:
    try:
        import tomli as tomllib
    except ImportError:
        tomllib = None

CONFIG_DIR = Path.home() / ".config" / "pipr"
CONFIG_FILE = CONFIG_DIR / "pipr.toml"
HISTORY_FILE = CONFIG_DIR / "history"
BOOKMARKS_FILE = CONFIG_DIR / "bookmarks"


def load_config() -> dict:
    defaults = {
        'paranoid_history_mode_default': False,
        'autoeval_mode_default': True,
        'history_size': 500,
        'cmdlist_always_show_preview': False,
        'cmd_timeout_millis': 2000,
        'highlighting_enabled': True,
        'eval_environment': ['bash', '-c'],
        'snippets': {'s': " | sed -r 's/||//g'"},
        'help_viewers': {'m': 'man ??', 'h': '?? --help | less'},
        'output_viewers': {'l': 'less'},
        'finish_hook': None,
    }
    if CONFIG_FILE.exists() and tomllib is not None:
        try:
            with open(CONFIG_FILE, 'rb') as f:
                file_cfg = tomllib.load(f)
            for k, v in file_cfg.items():
                if k == 'snippets':
                    defaults['snippets'] = {sk.strip("'"): sv for sk, sv in v.items()}
                elif k == 'help_viewers':
                    defaults['help_viewers'] = {hk.strip("'"): hv for hk, hv in v.items()}
                elif k == 'output_viewers':
                    defaults['output_viewers'] = {ok.strip("'"): ov for ok, ov in v.items()}
                else:
                    defaults[k] = v
        except Exception:
            pass
    return defaults


def parse_entries(content: str) -> List[str]:
    """Parse entries from file content using ---\n separator"""
    if not content:
        return []
    parts = content.split('\n---\n')
    return [p for p in parts if p]


def format_entries(entries: List[str]) -> str:
    """Format entries for saving to file"""
    return '\n---\n'.join(entries)


def load_history() -> List[str]:
    if HISTORY_FILE.exists():
        try:
            return parse_entries(HISTORY_FILE.read_text())
        except Exception:
            pass
    return []


def save_history(entries: List[str]):
    try:
        CONFIG_DIR.mkdir(parents=True, exist_ok=True)
        HISTORY_FILE.write_text(format_entries(entries))
    except Exception:
        pass


def load_bookmarks() -> List[str]:
    if BOOKMARKS_FILE.exists():
        try:
            return parse_entries(BOOKMARKS_FILE.read_text())
        except Exception:
            pass
    return []


def save_bookmarks(bookmarks: List[str]):
    try:
        CONFIG_DIR.mkdir(parents=True, exist_ok=True)
        BOOKMARKS_FILE.write_text(format_entries(bookmarks))
    except Exception:
        pass


def run_command(env: List[str], cmd: str, timeout_ms: int) -> Tuple[str, str]:
    if not cmd.strip():
        return '', ''
    if not env:
        return '', 'No eval environment configured'
    try:
        proc = subprocess.Popen(
            env + [cmd],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )
        try:
            stdout, stderr = proc.communicate(timeout=timeout_ms / 1000.0)
            return (stdout.decode('utf-8', errors='replace'),
                    stderr.decode('utf-8', errors='replace'))
        except subprocess.TimeoutExpired:
            proc.kill()
            proc.communicate()
            return '', 'Command timed out'
    except Exception as e:
        return '', f'Error: {e}'


class TextBuffer:
    def __init__(self, text: str = ''):
        self.lines = text.split('\n') if text else ['']
        self.row = len(self.lines) - 1
        self.col = len(self.lines[self.row])

    def to_raw(self) -> str:
        return '\n'.join(self.lines)

    def to_command(self, raw: bool = False) -> str:
        filtered = [l for l in self.lines if not l.lstrip().startswith('#')]
        return '\n'.join(filtered) if raw else ' '.join(filtered)

    def insert_char(self, ch: str):
        line = self.lines[self.row]
        self.lines[self.row] = line[:self.col] + ch + line[self.col:]
        self.col += 1

    def insert_newline(self):
        line = self.lines[self.row]
        self.lines[self.row] = line[:self.col]
        self.lines.insert(self.row + 1, line[self.col:])
        self.row += 1
        self.col = 0

    def backspace(self):
        if self.col > 0:
            line = self.lines[self.row]
            self.lines[self.row] = line[:self.col-1] + line[self.col:]
            self.col -= 1
        elif self.row > 0:
            prev_len = len(self.lines[self.row - 1])
            self.lines[self.row - 1] += self.lines[self.row]
            del self.lines[self.row]
            self.row -= 1
            self.col = prev_len

    def delete_forward(self):
        line = self.lines[self.row]
        if self.col < len(line):
            self.lines[self.row] = line[:self.col] + line[self.col+1:]
        elif self.row + 1 < len(self.lines):
            self.lines[self.row] += self.lines[self.row + 1]
            del self.lines[self.row + 1]

    def move_left(self):
        if self.col > 0:
            self.col -= 1
        elif self.row > 0:
            self.row -= 1
            self.col = len(self.lines[self.row])

    def move_right(self):
        if self.col < len(self.lines[self.row]):
            self.col += 1
        elif self.row + 1 < len(self.lines):
            self.row += 1
            self.col = 0

    def move_home(self):
        self.col = 0

    def move_end(self):
        self.col = len(self.lines[self.row])

    def move_up(self):
        if self.row > 0:
            self.row -= 1
            self.col = min(self.col, len(self.lines[self.row]))

    def move_down(self):
        if self.row + 1 < len(self.lines):
            self.row += 1
            self.col = min(self.col, len(self.lines[self.row]))

    def delete_word_back(self):
        line = self.lines[self.row]
        if self.col == 0:
            if self.row > 0:
                self.backspace()
            return
        pos = self.col
        while pos > 0 and line[pos-1] == ' ':
            pos -= 1
        while pos > 0 and line[pos-1] != ' ':
            pos -= 1
        self.lines[self.row] = line[:pos] + line[self.col:]
        self.col = pos

    def clear(self):
        self.lines = ['']
        self.row = 0
        self.col = 0

    def char_at_cursor(self) -> Optional[str]:
        line = self.lines[self.row]
        if self.col < len(line):
            return line[self.col]
        return None

    def abs_cursor_pos(self) -> int:
        pos = sum(len(l) + 1 for l in self.lines[:self.row])
        return pos + self.col

    def word_at_cursor(self) -> str:
        line = self.lines[self.row]
        if not line:
            return ''
        col = min(self.col, len(line) - 1)
        start = col
        while start > 0 and line[start-1] not in (' ', '|', '<', '>', ';'):
            start -= 1
        end = col
        while end < len(line) and line[end] not in (' ', '|', '<', '>', ';'):
            end += 1
        return line[start:end]

    def first_word_of_line(self) -> str:
        parts = self.lines[self.row].split()
        return parts[0] if parts else ''

    def insert_str(self, s: str):
        for ch in s:
            if ch == '\n':
                self.insert_newline()
            else:
                self.insert_char(ch)


class App:
    def __init__(self, config: dict, initial_text: Optional[str], raw_mode: bool,
                 out_file: Optional[str], no_isolation: bool):
        self.config = config
        self.raw_mode = raw_mode
        self.out_file = out_file
        self.no_isolation = no_isolation

        self.buf = TextBuffer(initial_text or '')
        self.autoeval = config['autoeval_mode_default']
        self.paranoid = config['paranoid_history_mode_default']

        self.history = load_history()
        self.history_nav_idx = None
        self.bookmarks = load_bookmarks()

        self.stdout_lines: List[str] = []
        self.stderr_lines: List[str] = []
        self.output_stale = True

        self.cache_active = False
        self.cache_prefix: Optional[str] = None
        self.cache_output: Optional[str] = None

        self.is_bookmarked = self._check_bookmarked()
        self.mode = 'normal'
        self.list_sel = 0

        # Always evaluate on startup to set proper stale state
        self._evaluate()

    def _check_bookmarked(self) -> bool:
        raw = self.buf.to_raw()
        return raw in self.bookmarks

    def _build_eval_cmd(self) -> str:
        lines = self.buf.lines
        filtered = [l for l in lines if not l.lstrip().startswith('#')]
        joined = ' '.join(filtered)
        if self.cache_active and self.cache_prefix is not None and self.cache_output is not None:
            pipe_pos = joined.find('|')
            if pipe_pos >= 0:
                suffix = joined[pipe_pos:]
                escaped = self.cache_output.replace("'", "'\\''")
                return f"printf '%s' '{escaped}' {suffix}"
        return joined

    def _evaluate(self):
        cmd = self._build_eval_cmd()
        if not cmd.strip():
            self.stdout_lines = []
            self.stderr_lines = []
            self.output_stale = False
            return
        env = self.config['eval_environment']
        timeout_ms = self.config['cmd_timeout_millis']
        stdout, stderr = run_command(env, cmd, timeout_ms)
        if stdout.endswith('\n'):
            stdout = stdout[:-1]
        if stderr.endswith('\n'):
            stderr = stderr[:-1]
        self.stdout_lines = stdout.split('\n') if stdout else []
        self.stderr_lines = stderr.split('\n') if stderr else []
        self.output_stale = False

    def on_text_change(self):
        self.is_bookmarked = self._check_bookmarked()
        self.output_stale = True
        if self.cache_active and self.cache_prefix is not None:
            current = ' '.join(l for l in self.buf.lines if not l.lstrip().startswith('#'))
            if not current.startswith(self.cache_prefix):
                self.cache_active = False
                self.cache_prefix = None
                self.cache_output = None
        if self.autoeval:
            self._evaluate()
            if self.paranoid and not self.stderr_lines:
                raw = self.buf.to_raw()
                if raw.strip():
                    self._push_history(raw)

    def _push_history(self, entry: str):
        if not entry.strip():
            return
        if self.history and self.history[-1] == entry:
            return
        self.history.append(entry)
        max_size = self.config['history_size']
        if len(self.history) > max_size:
            self.history = self.history[-max_size:]
        self.history_nav_idx = None
        save_history(self.history)

    def evaluate_and_save(self):
        self._evaluate()
        raw = self.buf.to_raw()
        if raw.strip():
            self._push_history(raw)

    def toggle_bookmark(self):
        raw = self.buf.to_raw()
        if not raw.strip():
            return
        if self.is_bookmarked:
            self.bookmarks = [b for b in self.bookmarks if b != raw]
            self.is_bookmarked = False
        else:
            self.bookmarks.append(raw)
            self.is_bookmarked = True
        save_bookmarks(self.bookmarks)

    def toggle_cache(self):
        if self.cache_active:
            self.cache_active = False
            self.cache_prefix = None
            self.cache_output = None
            return
        ch = self.buf.char_at_cursor()
        if ch == '|':
            full = self.buf.to_raw()
            pos = self.buf.abs_cursor_pos()
            prefix_raw = full[:pos]
            filtered = ' '.join(l for l in prefix_raw.split('\n')
                                if not l.lstrip().startswith('#'))
            env = self.config['eval_environment']
            timeout_ms = self.config['cmd_timeout_millis']
            stdout, _ = run_command(env, filtered, timeout_ms)
            if stdout.endswith('\n'):
                stdout = stdout[:-1]
            self.cache_prefix = filtered
            self.cache_output = stdout
            self.cache_active = True

    def history_prev(self):
        if not self.history:
            return
        if self.history_nav_idx is None:
            self.history_nav_idx = len(self.history) - 1
        elif self.history_nav_idx > 0:
            self.history_nav_idx -= 1
        entry = self.history[self.history_nav_idx]
        self.buf = TextBuffer(entry)
        self.is_bookmarked = self._check_bookmarked()
        self.output_stale = True
        if self.autoeval:
            self._evaluate()

    def history_next(self):
        if self.history_nav_idx is None:
            return
        self.history_nav_idx += 1
        if self.history_nav_idx >= len(self.history):
            self.history_nav_idx = None
            self.buf = TextBuffer('')
        else:
            self.buf = TextBuffer(self.history[self.history_nav_idx])
        self.is_bookmarked = self._check_bookmarked()
        self.output_stale = True
        if self.autoeval:
            self._evaluate()

    def get_help_word(self) -> str:
        word = self.buf.word_at_cursor()
        if not word:
            word = self.buf.first_word_of_line()
        return word

    def insert_snippet(self, key: str):
        snippets = self.config.get('snippets', {})
        if key not in snippets:
            return
        snippet = snippets[key]
        if '||' in snippet:
            before, after = snippet.split('||', 1)
            self.buf.insert_str(before)
            saved = (self.buf.row, self.buf.col)
            self.buf.insert_str(after)
            self.buf.row, self.buf.col = saved
        else:
            self.buf.insert_str(snippet)
        self.on_text_change()


# ---- Drawing ----

def addstr_safe(stdscr, y: int, x: int, s: str, attr=0):
    try:
        if attr:
            stdscr.addstr(y, x, s, attr)
        else:
            stdscr.addstr(y, x, s)
    except curses.error:
        pass


def box_top(width: int, title: str, leading_space: bool = True) -> str:
    if leading_space:
        line = ' ┌ ' + title + ' '
        dashes = width - len(line) - 1
        return line + '─' * max(0, dashes) + '┐'
    else:
        line = '┌ ' + title + ' '
        dashes = width - len(line) - 1
        return line + '─' * max(0, dashes) + '┐'


def box_bottom(width: int, help_text: bool = False, leading_space: bool = True) -> str:
    if help_text:
        help_str = 'Help: F1'
        trailer = '──┘'
        pfx = ' └' if leading_space else '└'
        dashes = width - len(pfx) - len(help_str) - len(trailer)
        return pfx + '─' * max(0, dashes) + help_str + trailer
    else:
        pfx = ' └' if leading_space else '└'
        return pfx + '─' * max(0, width - len(pfx) - 1) + '┘'


def box_row(width: int, content: str, leading_space: bool = True) -> str:
    if leading_space:
        inner = width - 3
        return ' │' + content[:inner].ljust(inner) + '│'
    else:
        inner = width - 2
        return '│' + content[:inner].ljust(inner) + '│'


def build_cmd_title(app: App) -> str:
    parts = ['Command']
    if app.is_bookmarked:
        parts.append('Bookmarked')
    if app.autoeval:
        parts.append('Autoeval')
    if app.cache_active:
        parts.append('Caching')
    if app.paranoid:
        parts.append('Paranoid')
    if len(parts) == 1:
        return parts[0]
    return parts[0] + ' [' + '] ['.join(parts[1:]) + ']'


def draw_screen(stdscr, app: App):
    stdscr.erase()
    height, width = stdscr.getmaxyx()
    W = width - 1  # avoid last column
    draw_height = height - 2  # rows 1..height-2

    if app.mode == 'help':
        _draw_help(stdscr, 1, 0, W, draw_height)

    elif app.mode in ('history', 'bookmarks'):
        panel_h = 10
        if app.mode == 'history':
            title = 'History'
            items = app.history
        else:
            title = 'Bookmarks'
            items = app.bookmarks
        _draw_list_panel(stdscr, 1, 0, W, panel_h, title, items, app.list_sel)
        # Help: F1 standalone at same column as in box bottom border
        help_str = 'Help: F1'
        # Position: W - 3 - len(help_str) = W - 11
        hx = W - 3 - len(help_str)
        addstr_safe(stdscr, height - 2, hx, help_str)

    elif app.mode in ('snippets', 'help_viewer', 'output_viewer'):
        # Popup: left box (leading space) width=32, right box (no leading space) from col 32
        left_w = 32
        right_x = 32
        right_w = W - 32

        if app.mode == 'snippets':
            title = 'Open in'
            items = [(k, v.replace('||', '')) for k, v in sorted(app.config.get('snippets', {}).items())]
        elif app.mode == 'help_viewer':
            title = 'Open in'
            word = app.get_help_word()
            items = [(k, v.replace('??', word)) for k, v in sorted(app.config.get('help_viewers', {}).items())]
        else:
            title = 'Open in'
            items = [(k, v) for k, v in sorted(app.config.get('output_viewers', {}).items())]

        _draw_popup(stdscr, 1, 0, left_w, draw_height, title, items)
        _draw_main(stdscr, app, 1, right_x, right_w, draw_height, leading_space=False)

    else:
        _draw_main(stdscr, app, 1, 0, W, draw_height, leading_space=True)

    stdscr.refresh()


def _draw_help(stdscr, y: int, x: int, width: int, height: int):
    addstr_safe(stdscr, y, x, box_top(width, 'Help'))
    help_lines = [
        'F1         Show/hide help',
        'F2         Toggle autoeval',
        'F3         Toggle Paranoid history (fills up history in autoeval)',
        'F4         Show/hide history',
        'Ctrl+B     Show/hide bookmarks',
        'F5         Open helpviewer',
        'F6         Open outputviewer',
        'F7         When the cursor is on a `|` symbol, cache the output of everythin',
        'Ctrl+S     Save bookmark',
        'Alt+Return Newline',
        'Ctrl+U     Clear Command',
        'Ctrl+P     Previous in history',
        'Ctrl+N     Next in history',
        'Ctrl+V     Insert snippet (press corresponding key to choose)',
        '',
        'disable a line by starting it with a #',
        'this will simply exclude the line from the executed command.',
        '',
        'Config file is in',
        '~/.config/pipr/pipr.toml',
    ]
    for i in range(height - 2):
        content = help_lines[i] if i < len(help_lines) else ''
        addstr_safe(stdscr, y + 1 + i, x, box_row(width, content))
    addstr_safe(stdscr, y + height - 1, x, box_bottom(width, help_text=True))


def _draw_list_panel(stdscr, y: int, x: int, width: int, height: int,
                     title: str, items: List[str], sel: int):
    addstr_safe(stdscr, y, x, box_top(width, title))
    inner = height - 2
    for i in range(inner):
        content = ''
        if i < len(items):
            display = items[i].replace('\n', ' ↵ ')
            prefix = '>>' if i == sel else '  '
            content = prefix + display
        addstr_safe(stdscr, y + 1 + i, x, box_row(width, content))
    addstr_safe(stdscr, y + height - 1, x, box_bottom(width, help_text=False))


def _draw_popup(stdscr, y: int, x: int, width: int, height: int,
                title: str, items: List[Tuple[str, str]]):
    addstr_safe(stdscr, y, x, box_top(width, title))
    for i in range(height - 2):
        content = f'{items[i][0]}: {items[i][1]}' if i < len(items) else ''
        addstr_safe(stdscr, y + 1 + i, x, box_row(width, content))
    addstr_safe(stdscr, y + height - 1, x, box_bottom(width, help_text=False))


def _draw_main(stdscr, app: App, y: int, x: int, width: int, height: int, leading_space: bool = True):
    cmd_title = build_cmd_title(app)
    has_stderr = bool(app.stderr_lines)

    # Command box (3 rows)
    addstr_safe(stdscr, y, x, box_top(width, cmd_title, leading_space))
    cmd_content = app.buf.lines[0] if app.buf.lines else ''
    addstr_safe(stdscr, y + 1, x, box_row(width, cmd_content, leading_space))
    addstr_safe(stdscr, y + 2, x, box_bottom(width, False, leading_space))

    # Output / Stderr
    remaining = height - 3
    if has_stderr:
        out_h = remaining - remaining // 2
        err_h = remaining // 2
    else:
        out_h = remaining
        err_h = 0

    out_title = 'Output [+]' if app.output_stale else 'Output'
    out_y = y + 3
    addstr_safe(stdscr, out_y, x, box_top(width, out_title, leading_space))
    for i in range(out_h - 2):
        content = app.stdout_lines[i] if i < len(app.stdout_lines) else ''
        addstr_safe(stdscr, out_y + 1 + i, x, box_row(width, content, leading_space))
    out_bot = out_y + out_h - 1
    addstr_safe(stdscr, out_bot, x, box_bottom(width, (not has_stderr), leading_space))

    if has_stderr:
        err_y = out_y + out_h
        addstr_safe(stdscr, err_y, x, box_top(width, 'Stderr', leading_space))
        for i in range(err_h - 2):
            content = app.stderr_lines[i] if i < len(app.stderr_lines) else ''
            addstr_safe(stdscr, err_y + 1 + i, x, box_row(width, content, leading_space))
        addstr_safe(stdscr, err_y + err_h - 1, x, box_bottom(width, True, leading_space))

    # Cursor (only in primary view)
    if leading_space and app.mode == 'normal':
        cx = x + 2 + app.buf.col
        cy = y + 1 + app.buf.row
        try:
            stdscr.move(cy, cx)
        except curses.error:
            pass


def run_external(cmd: str, stdin_data: str = ''):
    curses.endwin()
    if stdin_data:
        proc = subprocess.Popen(['sh', '-c', cmd], stdin=subprocess.PIPE)
        proc.communicate(input=stdin_data.encode())
    else:
        proc = subprocess.Popen(['sh', '-c', cmd])
        proc.wait()


def main_loop(stdscr, app: App):
    curses.curs_set(1)
    stdscr.keypad(True)
    curses.noecho()
    curses.cbreak()
    curses.set_escdelay(25)

    while True:
        draw_screen(stdscr, app)

        try:
            ch = stdscr.get_wch()
        except curses.error:
            continue

        ch_int = ord(ch) if isinstance(ch, str) else ch

        # Handle ESC (may be Alt+key)
        if ch_int == 27:
            stdscr.timeout(50)
            got_next = False
            try:
                next_ch = stdscr.get_wch()
                got_next = True
            except curses.error:
                pass
            stdscr.timeout(-1)

            if got_next:
                next_int = ord(next_ch) if isinstance(next_ch, str) else next_ch
                if next_int in (10, 13, curses.KEY_ENTER):
                    if app.mode == 'normal':
                        app.buf.insert_newline()
                        app.on_text_change()
                    continue
                # Other alt combinations - treat as ESC

            # Process ESC: quit from normal, close panel otherwise
            if app.mode == 'normal':
                return
            else:
                app.mode = 'normal'
            continue

        if app.mode == 'normal':
            handle_normal(stdscr, app, ch, ch_int)
        elif app.mode == 'help':
            if ch_int == curses.KEY_F1:
                app.mode = 'normal'
        elif app.mode in ('history', 'bookmarks'):
            handle_list(stdscr, app, ch, ch_int)
        elif app.mode in ('snippets', 'help_viewer', 'output_viewer'):
            handle_menu(stdscr, app, ch, ch_int)

        if app.mode == 'quit':
            return


def handle_normal(stdscr, app: App, ch, ch_int: int):
    if ch_int == curses.KEY_F1:
        app.mode = 'help'
    elif ch_int == curses.KEY_F2:
        app.autoeval = not app.autoeval
        if app.autoeval:
            app._evaluate()
    elif ch_int == curses.KEY_F3:
        app.paranoid = not app.paranoid
    elif ch_int == curses.KEY_F4:
        app.mode = 'history'
        app.list_sel = max(0, len(app.history) - 1)
    elif ch_int == curses.KEY_F5:
        app.mode = 'help_viewer'
    elif ch_int == curses.KEY_F6:
        app.mode = 'output_viewer'
    elif ch_int == curses.KEY_F7:
        app.toggle_cache()
        if app.autoeval:
            app._evaluate()
    elif ch_int == 19:  # Ctrl+S
        app.toggle_bookmark()
    elif ch_int == 2:  # Ctrl+B
        app.mode = 'bookmarks'
        app.list_sel = max(0, len(app.bookmarks) - 1)
    elif ch_int == 22:  # Ctrl+V
        app.mode = 'snippets'
    elif ch_int == 21:  # Ctrl+U
        app.buf.clear()
        app.on_text_change()
    elif ch_int == 23:  # Ctrl+W
        app.buf.delete_word_back()
        app.on_text_change()
    elif ch_int == 16:  # Ctrl+P
        app.history_prev()
    elif ch_int == 14:  # Ctrl+N
        app.history_next()
    elif ch_int in (10, 13, curses.KEY_ENTER):
        app.evaluate_and_save()
    elif ch_int in (curses.KEY_BACKSPACE, 127, 8):
        app.buf.backspace()
        app.on_text_change()
    elif ch_int == curses.KEY_DC:
        app.buf.delete_forward()
        app.on_text_change()
    elif ch_int == curses.KEY_LEFT:
        app.buf.move_left()
    elif ch_int == curses.KEY_RIGHT:
        app.buf.move_right()
    elif ch_int == curses.KEY_UP:
        app.buf.move_up()
    elif ch_int == curses.KEY_DOWN:
        app.buf.move_down()
    elif ch_int == curses.KEY_HOME:
        app.buf.move_home()
    elif ch_int == curses.KEY_END:
        app.buf.move_end()
    elif ch_int == curses.KEY_RESIZE:
        pass
    elif isinstance(ch, str) and ch_int >= 32:
        app.buf.insert_char(ch)
        app.on_text_change()


def handle_list(stdscr, app: App, ch, ch_int: int):
    ltype = app.mode
    items = app.history if ltype == 'history' else app.bookmarks
    n = len(items)

    if ch_int == curses.KEY_F4 and ltype == 'history':
        app.mode = 'normal'
    elif ch_int == 2 and ltype == 'bookmarks':
        app.mode = 'normal'
    elif ch_int in (curses.KEY_UP, 16):  # Up, Ctrl+P
        if app.list_sel > 0:
            app.list_sel -= 1
    elif ch_int in (curses.KEY_DOWN, 14):  # Down, Ctrl+N
        if app.list_sel < n - 1:
            app.list_sel += 1
    elif ch_int in (10, 13, curses.KEY_ENTER):
        if 0 <= app.list_sel < n:
            app.buf = TextBuffer(items[app.list_sel])
            app.mode = 'normal'
            app.is_bookmarked = app._check_bookmarked()
            app.output_stale = True
            if app.autoeval:
                app._evaluate()
    elif ch_int == curses.KEY_DC:
        if ltype == 'bookmarks' and 0 <= app.list_sel < n:
            del app.bookmarks[app.list_sel]
            save_bookmarks(app.bookmarks)
            new_n = len(app.bookmarks)
            if new_n > 0:
                app.list_sel = min(app.list_sel, new_n - 1)
            app.is_bookmarked = app._check_bookmarked()


def handle_menu(stdscr, app: App, ch, ch_int: int):
    if not isinstance(ch, str):
        app.mode = 'normal'
        return
    key = ch
    mode = app.mode
    app.mode = 'normal'

    if mode == 'snippets':
        app.insert_snippet(key)
    elif mode == 'help_viewer':
        viewers = app.config.get('help_viewers', {})
        if key in viewers:
            word = app.get_help_word()
            cmd = viewers[key].replace('??', word)
            run_external(cmd)
    elif mode == 'output_viewer':
        viewers = app.config.get('output_viewers', {})
        if key in viewers:
            stdout_data = '\n'.join(app.stdout_lines)
            run_external(viewers[key], stdout_data)


